  "{0}: “Bu kür seni {1} dövüş boyunca canavara çevirir. Testlerde çıkmaz… genelde.” Fiyatı {2}.\n\nKabul edersen vuruş, kondisyon, hız ve çene ciddi artar. Yakalanırsan 6 ay ile 2 yıl arası men, popülerlik kaybı ve sponsor iptali.": "{0}: „Diese Kur macht dich {1} Kämpfe lang zum Monster. Bei Tests fällt sie nicht auf… meistens.“ Der Preis: {2}.\n\nNimmst du an, steigen Schlagkraft, Kondition, Schnelligkeit und Kinn deutlich. Wirst du erwischt: 6 Monate bis 2 Jahre Sperre, Popularitätsverlust und gekündigte Sponsoren.",
  "Kabul et": "Annehmen",
  "Federasyona ihbar et": "Der Kommission melden",
  "Kürü aldın. Aynada başka biri var. Sonraki {0} dövüşte çok güçlüsün… ama her dövüşten sonra test riski var.": "Du hast die Kur genommen. Im Spiegel steht jemand anderes. In den nächsten {0} Kämpfen bist du sehr stark… aber nach jedem Kampf droht ein Test.",
  "Kibarca reddettin. Temiz bir kariyer, huzurlu bir uyku.": "Du hast höflich abgelehnt. Eine saubere Karriere, ein ruhiger Schlaf.",
  "Federasyona ihbar ettin. Basın seni “temiz sporun sesi” ilan etti. Popülerlik +2.": "Du hast es der Kommission gemeldet. Die Presse nannte dich „die Stimme des sauberen Sports“. Popularität +2.",
  "💼 Sponsorluk Teklifi": "💼 Sponsorenangebot",
  "Bahis": "Wetten",
  "\n\nAma bir bahis şirketi… Bazı taraftarların hoşuna gitmeyebilir.": "\n\nAber es ist ein Wettanbieter… Manchen Fans könnte das nicht gefallen.",
  "{0} seninle çalışmak istiyor. Şortunda logoları olacak, karşılığında {1} ödeyecekler.{2}": "{0} will mit dir zusammenarbeiten. Ihre Logos kommen auf deine Shorts, dafür zahlen sie dir {1}.{2}",
  "Pazarlık yap (+%50 dene)": "Verhandeln (+50 % versuchen)",
  " (Bazı taraftarlar tepkili: popülerlik -2)": " (Manche Fans sind unzufrieden: Popularität -2)",
