  "Teklifi reddettin. İmajın temiz kaldı.": "Du hast das Angebot abgelehnt. Dein Image bleibt sauber.",
  "Antrenmanda sparring partnerini uyuttuğun bir video 2 milyon izlendi. Yorumlar ikiye bölünmüş durumda. Ne paylaşırsın?": "Ein Video, in dem du deinen Sparringspartner K.o. schlägst, hat 2 Millionen Aufrufe. Die Kommentare sind gespalten. Was postest du?",
