  "Paylaşımın ortalığı yıktı. Rakipler cevap yazıyor, gazeteciler seni arıyor. Popülerlik +5.": "Dein Beitrag ist explodiert. Rivalen antworten, Journalisten rufen an. Popularität +5.",
