  "Menajer {0} (kalite {1}/10) seni temsil etmek istiyor. Tüm kazançlarından %{2} alacak. Karşılığında kontrat pazarlıkları ve sponsorluklar çok daha kolay olacak.": "Manager {0} (Qualität {1}/10) will dich vertreten. Er bekommt {2} % all deiner Einnahmen. Dafür werden Vertragsverhandlungen und Sponsoren viel einfacher.",
