  "Parayı gönderdin. Ameliyat başarılı geçti. Babanın mesajı: \"Oğlumla gurur duyuyorum.\" Motivasyonun tavan.": "Du hast das Geld geschickt. Die Operation ist gut verlaufen. Die Nachricht deines Vaters: „Ich bin stolz auf dich.“ Deine Motivation ist auf dem Höhepunkt.",
  "Yarısını gönderdin, gerisini akrabalar tamamladı. İçin rahat.": "Du hast die Hälfte geschickt, die Verwandten haben den Rest übernommen. Dein Gewissen ist rein.",
  "Yapamadığını söyledin. Telefonu kapattıktan sonra uzun süre tavana baktın. Motivasyon düştü.": "Du hast gesagt, dass du nicht kannst. Nach dem Auflegen hast du lange an die Decke gestarrt. Die Motivation ist gesunken.",
