  "🎯 {0} vuruştan önce omzunu düşürüyor. Bir açık gördün… ya da bu bir yem.": "🎯 {0} senkt vor dem Schlag die Schulter. Du hast eine Lücke entdeckt… oder es ist ein Köder.",
