  "🏟️ Salon ayakta, adını bağırıyor!": "🏟️ Die Halle steht und skandiert deinen Namen!",
  "Şov yap": "Show machen",
  "Ellerini indir, rakibi davet et. Popülerlik getirir, risklidir.": "Nimm die Hände runter, lad ihn ein. Bringt Popularität, ist riskant.",
  "Ellerini indirip rakibini çağırdın! Salon yıkılıyor!": "Du hast die Hände runtergenommen und ihn eingeladen! Die Halle rastet aus!",
