  "Onun oyununa gelme.": "Lass dich nicht auf sein Spiel ein.",
  "Duygularını kontrol ettin, zekânla dövüşüyorsun.": "Du hast deine Gefühle im Griff und kämpfst mit dem Kopf.",
  "Kapışmaya gir!": "Schlagabtausch!",
  "Göster ona. İki taraf da hasar alır.": "Zeig's ihm. Beide Seiten nehmen Schaden.",
  "Ortada kapışma başladı!": "In der Mitte ist ein Schlagabtausch ausgebrochen!",
  "— {0}. RAUNT — Sen: {1}": "— RUNDE {0} — Du: {1}",
  "🧠 {0} bu hamleyi bekliyordu. Aynı oyunu {1}. kez oynamak seni öngörülebilir yapıyor.": "🧠 {0} hat mit dieser Aktion gerechnet. Denselben Spielzug immer wieder zu spielen (jetzt {1} Mal), macht dich berechenbar.",
  "🔥 {0} üstüne çullanıyor, son yumruk {1} dövüşçüsünü kafesin zeminine gömüyor! NAKAVT!": "🔥 {0} setzt nach, der letzte Schlag nagelt {1} auf die Matte! KNOCKOUT!",
  "🔥 {0} yağmur gibi yumruk indiriyor, {1} karşılık veremiyor, hakem araya giriyor! TKO!": "🔥 {0} lässt Schläge regnen, {1} kann nicht antworten, der Ringrichter geht dazwischen! TKO!",
  "😱 {0} umutsuz bir kontra savurdu ve TAM İSABET! Durum tersine döndü!": "😱 {0} hat einen verzweifelten Konter geworfen und VOLL GETROFFEN! Das Blatt hat sich gewendet!",
  "{0} bir şekilde ayakta kaldı, zili bekliyor. Sen de çok yoruldun.": "{0} hat sich irgendwie auf den Beinen gehalten und wartet auf die Glocke. Du bist auch erschöpft.",
  "🎯 {0} hedef seçerek vuruyor, sağ-sol-sağ… hakem yeter diyor! TKO!": "🎯 {0} wählt die Schläge, rechts-links-rechts… der Ringrichter hat genug gesehen! TKO!",
  "{0} kontrollü vuruşlarla puan topluyor, rakip toparlanmaya çalışıyor.": "{0} punktet mit kontrollierten Schlägen, während sich der Gegner zu erholen versucht.",
  "{0} yere indirmek için daldı ama rakip son gücüyle savundu. Fırsat kaçtı.": "{0} ist auf einen Takedown gegangen, aber der Gegner hat sich mit allem gewehrt, was er hatte. Die Chance ist vorbei.",
  "🔨 {0} yerde mount aldı, ground and pound yağdırıyor, hakem durdurdu! TKO!": "🔨 {0} hat am Boden die Mount genommen und Ground and Pound geregnet, der Ringrichter hat abgebrochen! TKO!",
  "🔒 {0} sersem rakibin sırtını aldı ve {1} ile tap attırdı!": "🔒 {0} hat den Rücken des benommenen Gegners genommen und ihn mit {1} zur Aufgabe gezwungen!",
  "{0} yerde ağır vuruyor ama {1} bir şekilde hayatta kalıyor.": "{0} landet am Boden harte Treffer, aber {1} überlebt irgendwie.",
  "🔥 İnanılmaz! Sarsılmışken savurduğun sağ el {0} dövüşçüsünü de sarstı!": "🔥 Unglaublich! Die Rechte, die du angeschlagen geworfen hast, hat auch {0} wehgetan!",
  "Rakibine sarıldın, kafanı yasladın. Saniyeler geçiyor… toparlanıyorsun.": "Du bist in den Clinch und hast den Kopf angelehnt. Die Sekunden vergehen… du erholst dich.",
  "Ayakların seni taşıdı. Kafes boyunca dönüp mesafe açtın, kafan netleşiyor.": "Deine Beine haben dich getragen. Du hast den Käfig umkreist und Distanz geschaffen, dein Kopf wird klarer.",
  "Karşılık vermeye çalıştın, isabet etmedi ama o da bitiremedi. Hayattasın!": "Du wolltest zurückschlagen, es saß nicht, aber er konnte auch nicht beenden. Du hast überlebt!",
  "💀 {0} son darbeyi indirdi. Bilinçsiz yere yığıldın. NAKAVT.": "💀 {0} hat den letzten Schlag gelandet. Du bist bewusstlos zusammengebrochen. KNOCKOUT.",
  "💀 {0} yumruk yağdırıyor, kendini savunamıyorsun. Hakem durdurdu. TKO.": "💀 {0} lässt Schläge regnen, du kannst dich nicht verteidigen. Der Ringrichter hat abgebrochen. TKO.",
  "Ağır darbeler aldın ama ayaktasın. Zil seni kurtarmak zorunda.": "Du hast schwere Treffer eingesteckt, stehst aber noch. Die Glocke muss dich retten.",
  "🔒 {0} {1} kilidini sonuna kadar sıktı… {2} TAP ATTI!": "🔒 {0} hat {1} voll durchgezogen… {2} HAT ABGEKLOPFT!",
  "{0} son anda {1} kilidinden sıyrıldı ve ayağa kalktı!": "{0} ist in letzter Sekunde aus {1} geschlüpft und wieder aufgestanden!",
  "{0} riske girmiyor, üstte kalıp dirsek ve yumrukla puan topluyor.": "{0} geht auf Nummer sicher, bleibt oben und punktet mit Ellbogen und Schlägen.",
  "Tap attın. {0} {1} ile kazandı. Acı ama sağlıklısın.": "Du hast abgeklopft. {0} gewinnt durch {1}. Es tut weh, aber du bist gesund.",
  "Elleri kontrol ettin, açıyı kırdın ve {0} kilidinden çıktın!": "Du hast die Hände kontrolliert, den Winkel gebrochen und dich aus {0} befreit!",
  "Patlayıcı bir köprüyle sıyrıldın ve üste geçtin! Seyirci çıldırıyor!": "Du hast dich mit einer explosiven Brücke befreit und bist nach oben gekommen! Das Publikum flippt aus!",
  "🦴 Tap atmayı reddettin… bir çıtırtı. Hakem durdurdu. {0} {1} ile kazandı.": "🦴 Du wolltest nicht abklopfen… ein Knacken. Der Ringrichter hat abgebrochen. {0} gewinnt durch {1}.",
  "Kilidi açamadın. {0} {1} ile seni tap attırdı.": "Du konntest den Hebel nicht lösen. {0} hat dich mit {1} zur Aufgabe gezwungen.",
  "🔔 {0}. raunt bitti.": "🔔 Runde {0} ist vorbei.",
  "🩺 Ringside doktoru kesiğe bakıp başını salladı. Maç durduruldu. Doktor kararıyla TKO.": "🩺 Der Ringarzt hat sich den Cut angesehen und den Kopf geschüttelt. Der Kampf ist abgebrochen. TKO durch Arztentscheidung.",
  "🏳️ {0} köşesi havlu attı! Rakip raunda çıkamıyor. TKO!": "🏳️ Die Ecke von {0} hat das Handtuch geworfen! Der Gegner kann nicht mehr antreten. TKO!",
