  "Ellerimin ağır olduğunu söylemiştim. {raunt}. rauntta ışıkları kapattım!": "Ich hab euch gesagt, meine Hände sind schwer. In Runde {raunt} gingen die Lichter aus!",
  "Bu yumruğu kampta bin kez çalıştık. Bin birincisi {opp}’a geldi!": "Diesen Schlag haben wir im Camp tausendmal geübt. Der tausendunderste ging an {opp}!",
