  "Gecenin en çok paylaşılan anı senin yumruğun.": "Der meistgeteilte Moment des Abends ist dein Schlag.",
  "Yorumcular nakavtı “yılın nakavtı” adayı ilan etti.": "Die Kommentatoren nannten es einen Kandidaten für den „K.o. des Jahres“.",
