  "Bazıları “sıkıcı” dedi, ama kimse üstünlüğünü tartışmıyor.": "Manche nannten es „langweilig“, aber niemand bestreitet deine Dominanz.",
  "Teknik direktörler performansını analiz etti: “ders niteliğinde”.": "Trainer haben deine Leistung analysiert: „eine Meisterklasse“.",
  "Zor bir geceydi. Bir dahaki sefere işi hakemlere bırakmayacağım.": "Es war eine harte Nacht. Nächstes Mal überlasse ich es nicht den Punktrichtern.",
