  "Herkes bitti sandı. Ben bitmem!": "Alle dachten, ich bin fertig. Ich bin nie fertig!",
  "Rauntları kaybediyordum, köşem bana inandı. Kalbim kazandı bu maçı.": "Ich habe Runden verloren, meine Ecke hat an mich geglaubt. Mein Herz hat diesen Kampf gewonnen.",
