  "Seyirciler ayakta, iki savaşçıyı da alkışladı.": "Die Fans stehen und applaudieren beiden Kriegern.",
  "İlk profesyonel galibiyet! Bu anı ömrüm boyunca unutmayacağım.": "Mein erster Profisieg! Diesen Moment vergesse ich nie.",
