  "Seri devam ediyor. Sıklette beni durduracak kimse yok.": "Die Serie geht weiter. Niemand in dieser Gewichtsklasse kann mich stoppen.",
  "Seri istatistikleri ekranlarda. Herkes kimin durduracağını tartışıyor.": "Deine Seriendaten laufen über die Bildschirme. Alle diskutieren, wer dich stoppen wird.",
