  "Kampın {n}. haftası. Ciğerler yanıyor ama zihin berrak. 🥊": "Woche {n} im Camp. Die Lunge brennt, aber der Kopf ist klar. 🥊",
  "Sabah 5’te koşu, öğlen spar, akşam grappling. {rakip}, ben hazırım. #Kamp": "Laufen um 5 Uhr, Sparring mittags, Grappling abends. {rakip}, ich bin bereit. #Camp",
  "{hoca} bugün beni yere serdi. Kafeste kimse bunu yapamayacak. 😤": "{hoca} hat mich heute zu Boden gebracht. Im Käfig wird das niemand schaffen. 😤",
  "Yeni bir silah geliştiriyoruz. Maç gecesi göreceksiniz… 🤫": "Wir bauen eine neue Waffe. Ihr seht sie am Kampfabend… 🤫",
  "Kilo kontrolde, zihin net. {rakip} gelsin.": "Gewicht im Plan, Kopf klar. Her mit {rakip}.",
  "{salon}’da bir gece daha. Işıklar sönene kadar buradayım. 💡": "Noch eine Nacht im {salon}. Ich bleibe, bis das Licht ausgeht. 💡",
  "Bugün 10 raunt spar. Yoruldum ama durmadım.": "Heute 10 Runden Sparring. Müde, aber ich habe nicht aufgehört.",
  "Video analiz günü: {rakip}’in her hareketini ezberliyorum. 🎬": "Videotag: Ich lerne jede Bewegung von {rakip} auswendig. 🎬",
  "Buz banyosu, masaj, uyku. Savaşçı dinlenmeyi de bilir. 🧊": "Eisbad, Massage, Schlaf. Ein Krieger weiß auch, wie man ruht. 🧊",
  "Kamp güncellemesi: sağlıklı, aç ve tehlikeli. 🐺": "Camp-Update: gesund, hungrig und gefährlich. 🐺",
  "{rakip} kafeste beni görünce kaçacak yer arayacak. 😂": "{rakip} wird einen Fluchtweg suchen, wenn er mich im Käfig sieht. 😂",
  "{rakip}, sosyal medyada çok cesursun. Kafeste görüşürüz.": "{rakip}, in den sozialen Medien bist du sehr mutig. Wir sehen uns im Käfig.",
  "Bu gece {rakip} uyumayacak. Çünkü maç gecesi uyutacağım. 💤": "{rakip} wird heute Nacht nicht schlafen. Denn am Kampfabend schicke ich ihn schlafen. 💤",
  "{rakip} diye bir dövüşçü yok, sadece bir sonraki kurbanım var.": "Es gibt keinen Kämpfer namens {rakip}, nur mein nächstes Opfer.",
  "{rakip} hayranları, şimdiden mendilleri hazırlayın. 🤧": "Fans von {rakip}, haltet die Taschentücher bereit. 🤧",
  "{rakip}’in çenesi o kadar dayanıklı değil, herkes biliyor.": "Das Kinn von {rakip} ist nicht so stabil, das weiß jeder.",
  "Kamera önünde herkes aslan. Kafes kapısı kapanınca görürüz {rakip}.": "Vor der Kamera ist jeder ein Löwe. Wir sehen, wenn die Käfigtür zugeht, {rakip}.",
  "{rakip}, hazır ol. Kariyerinin en kötü gecesi yaklaşıyor.": "{rakip}, mach dich bereit. Die schlimmste Nacht deiner Karriere kommt.",
  "Söylediklerimin arkasındayım: {rakip} bu maçı bitiremeyecek.": "Ich stehe zu meinen Worten: {rakip} wird diesen Kampf nicht beenden.",
  "{sampiyon}, kemerini hazırla. Geliyorum. 🏆": "{sampiyon}, halt deinen Gürtel bereit. Ich komme. 🏆",
  "{sampiyon} benden kaçıyor. {org}, bu maçı yapın!": "{sampiyon} läuft vor mir weg. {org}, macht diesen Kampf!",
  "Sıklette kimse benimle dövüşmek istemiyor. Sıradaki kim? 👀": "Niemand in der Gewichtsklasse will gegen mich kämpfen. Wer ist der Nächste? 👀",
  "{sampiyon}, tahtında rahat oturma. Sıra bende.": "{sampiyon}, mach es dir auf dem Thron nicht bequem. Ich bin der Nächste.",
  "İlk 5’e giren herkese açık davet: kafeste görüşelim.": "Offene Einladung an alle in den Top 5: Wir sehen uns im Käfig.",
  "{org}, bana bir şampiyonluk maçı borçlusunuz. Hak ettim.": "{org}, ihr schuldet mir einen Titelkampf. Ich habe ihn mir verdient.",
  "Adımı unutmayın. Yakında o kemer bende olacak.": "Merkt euch meinen Namen. Bald gehört dieser Gürtel mir.",
  "{rakip} gerçek bir savaşçı. Maç gecesi en iyi hâlimizle karşılaşacağız. 🤝": "{rakip} ist ein echter Krieger. Am Kampfabend treffen wir uns in Bestform. 🤝",
  "Rakibime saygım sonsuz. Ama kazanan ben olacağım.": "Unendlicher Respekt für meinen Gegner. Aber gewinnen werde ich.",
  "{hoca} ve tüm takımıma teşekkürler. Bu yol tek başına yürünmez.": "Danke an {hoca} und mein ganzes Team. Niemand geht diesen Weg allein.",
  "Sıklette herkes çok çalışıyor. Bu yüzden bu spor güzel.": "Jeder in der Gewichtsklasse arbeitet hart. Das macht diesen Sport so schön.",
  "Yenildiğim her maç bana bir şey öğretti. Hepsine minnettarım.": "Jede Niederlage hat mich etwas gelehrt. Ich bin für alle dankbar.",
  "Rakiplerime saygı, taraftarlara sevgi. Gerisi kafeste. 🙏": "Respekt an meine Gegner, Liebe an die Fans. Der Rest passiert im Käfig. 🙏",
  "{takipci} kişi! İnanılmaz. Her birinize teşekkür ederim. ❤️": "{takipci} Leute! Unglaublich. Danke, jedem Einzelnen von euch. ❤️",
  "Maç gecesi tribünler yine bizim olsun! Kim geliyor? 🙌": "Lasst uns am Kampfabend wieder die Ränge übernehmen! Wer kommt? 🙌",
  "Bir taraftarım bugün bana el yazısı mektup verdi. Ağladım. 🥹": "Ein Fan hat mir heute einen handgeschriebenen Brief gegeben. Ich habe geweint. 🥹",
  "{memleket}, bu zafer senin için!": "{memleket}, dieser Sieg ist für dich!",
  "Sorularınızı yazın, en iyilerini bu akşam cevaplayacağım. 👇": "Schickt eure Fragen, die besten beantworte ich heute Abend. 👇",
  "Bu yolculukta yanımda olan herkese: sizin sayenizde buradayım.": "An alle, die mich auf dieser Reise begleitet haben: Ich bin wegen euch hier.",
  "Kimse sana inanmasa da sen kendine inan. 💯": "Glaub an dich, auch wenn es niemand sonst tut. 💯",
  "Ter antrenmanda akar ki kan kafeste akmasın.": "Schwitz im Training, damit du im Käfig nicht blutest.",
  "Düştüğün yer değil, kalktığın yer seni tanımlar.": "Nicht wo du fällst, sondern wo du aufstehst, zeigt, wer du bist.",
  "Bugün acı, yarın zafer. 🔥": "Heute Schmerz, morgen Sieg. 🔥",
  "Yetenek başlatır, disiplin bitirir.": "Talent bringt dich hin, Disziplin bringt es zu Ende.",
  "Her sabah aynı soru: bugün dünden daha iyi miyim?": "Jeden Morgen dieselbe Frage: Bin ich besser als gestern?",
  "Kolay olsaydı herkes şampiyon olurdu.": "Wäre es leicht, wäre jeder Champion.",
  "Bugün dinlenme günü. Ailemle kahvaltı. Savaşçılar da insan. ❤️": "Heute Ruhetag. Frühstück mit der Familie. Krieger sind auch Menschen. ❤️",
  "Yeni tatlı yasak listesi: hepsi. 🍰❌": "Neue Liste verbotener Desserts: alle. 🍰❌",
  "Bir kahve, biraz müzik, sonra tekrar salon. ☕🎧": "Ein Kaffee, etwas Musik, dann zurück ins Gym. ☕🎧",
  "Hayatımda iki şey var: kafes ve sevdiklerim.": "Zwei Dinge in meinem Leben: der Käfig und meine Liebsten.",
  "{sponsor} ile yola devam! Teşekkürler ekip. 🤝": "Es geht weiter mit {sponsor}! Danke, Team. 🤝",
  "Maç gecesi {sponsor} logosuyla kafesteyim. 💪": "Am Kampfabend im Käfig mit dem {sponsor}-Logo. 💪",
  "{sponsor} ailesine katılmak gurur verici. Birlikte zirveye!": "Stolz, Teil der {sponsor}-Familie zu sein. Gemeinsam nach oben!",
  "Soru: sıradaki maçımı nakavtla mı bitireyim, submission ile mi? 👇": "Frage: Soll ich meinen nächsten Kampf per K.o. oder per Aufgabe beenden? 👇",
  "Sizce sıklette en tehlikeli isim kim? Yorumlara yazın.": "Wer ist eurer Meinung nach der gefährlichste Name der Gewichtsklasse? Schreibt's in die Kommentare.",
  "Tüm zamanların en iyisi kim sizce? Tartışalım. 🐐": "Wer ist der Größte aller Zeiten? Lasst uns diskutieren. 🐐",
