  "Yüzümde morluk, kalbimde zafer. Teşekkürler herkese! ❤️": "Blaue Flecken im Gesicht, der Sieg im Herzen. Danke an euch alle! ❤️",
  "Bu gece o daha iyiydi. Salona dönüyorum, daha güçlü geleceğim.": "Er war heute besser. Ich gehe zurück ins Gym und komme stärker wieder.",
