  "Hakem kararlarına saygı duyuyorum ama katılmıyorum. Devam. ✊": "Ich respektiere die Entscheidung der Punktrichter, teile sie aber nicht. Weiter geht's. ✊",
  "Mesajlarınız için teşekkürler. Bu yenilgi hikâyemin sonu değil.": "Danke für eure Nachrichten. Diese Niederlage ist nicht das Ende meiner Geschichte.",
