  "{ph} ile aynı kafese girmek için sabırsızlanıyorum. Sabırsızlığım onun korkusundan büyük. 😈": "Ich kann es kaum erwarten, mit {ph} in den Käfig zu steigen. Meine Ungeduld ist größer als seine Angst. 😈",
  "Kamp raporu: {ph} dövüşünü 100 kez izledim. Açığını buldum. Sürpriz olmayacak.": "Camp-Bericht: Ich habe {ph} 100 Mal kämpfen sehen. Die Lücke ist gefunden. Keine Überraschungen.",
