  "{ph} mi? {org}’da bana verilen en kolay maç bu. {hafta} hafta sonra görürüz.": "{ph}? Der leichteste Kampf, den {org} mir je gegeben hat. Wir sehen uns in {hafta} Wochen.",
  "{ph} kafeste görüşürüz. Hastane masrafını ben öderim, merak etme.": "Wir sehen uns im Käfig, {ph}. Die Krankenhausrechnung übernehme ich, keine Sorge.",
  "Çenen cam gibi {p}. İlk sağ elimde dağılacak.": "Dein Kinn ist aus Glas, {p}. Bei meiner ersten Rechten zerspringt es.",
  "{ph} sosyal medyada çok cesur. Bakalım kafes kapısı kapanınca da öyle mi?": "{ph} ist in den sozialen Medien sehr mutig. Mal sehen, ob das hält, wenn die Käfigtür zugeht.",
  "Herkes {p} diyor… Ben kimseyi görmüyorum. 🥱": "Alle reden von {p}… ich sehe niemanden. 🥱",
  "{ph} taraftarlarına söyleyin, mendillerini hazırlasınlar.": "Sagt den Fans von {ph}, sie sollen die Taschentücher bereithalten.",
  "{ph} kariyerini takip ediyorum, ciddi bir yetenek. Ama bu gece benim gecem olacak.": "Ich habe die Karriere von {ph} verfolgt, ein echtes Talent. Aber heute Nacht gehört mir.",
  "Bu maç ikimiz için de büyük fırsat. {ph}, sağlıklı bir kamp dilerim.": "Dieser Kampf ist eine große Chance für uns beide. {ph}, hab ein gesundes Camp.",
  "{ph} ile dövüşmek onur. Hazırlığım tam, en iyi hâlimle geleceğim.": "Eine Ehre, gegen {ph} zu kämpfen. Meine Vorbereitung ist abgeschlossen, ich komme in Bestform.",
  "Saygı duyduğum bir rakip: {ph}. Ama kazanan ben olacağım.": "Ein Gegner, den ich respektiere: {ph}. Aber gewinnen werde ich.",
  "Kamp bitti. {ph}, iyi bir savaş olsun. 🤝": "Das Camp ist vorbei. {ph}, lass uns einen guten Krieg führen. 🤝",
  "{ph} söylemiştim. Sıradaki! 👋": "Hab ich doch gesagt, {ph}. Der Nächste! 👋",
  "Bu gece bir şey kanıtladım. {ph}, iyi dövüştün ama yeterli değildi.": "Ich habe heute etwas bewiesen. {ph}, du hast gut gekämpft, aber es hat nicht gereicht.",
