  "Karakterini Nasıl Kurarsın?": "Wie baust du deinen Charakter?",
  "🌍 Uyruk: Antrenman imkânı başlangıç istatistiklerini, taraftar desteği başlangıç popülerliğini belirler. İlk salonun ve hocan da ülkene göre gelir.": "🌍 Nationalität: Die Trainingsmöglichkeiten bestimmen deine Startwerte, der Rückhalt der Fans deine Start-Popularität. Auch dein erstes Gym und dein Trainer hängen von deinem Land ab.",
  "🎂 Yaş (18-30): Genç başlarsan ham ama hızlı gelişirsin (×1.3). Yaşlı başlarsan güçlü başlarsın ama 32’den sonra hız ve çene düşmeye başlar. 41’de emeklilik kaçınılmazdır.": "🎂 Alter (18–30): Startest du jung, bist du roh, wächst aber schnell (×1,3). Startest du älter, bist du stärker, aber ab 32 lassen Schnelligkeit und Kinn nach. Mit 41 ist das Karriereende unvermeidlich.",
  "⚖️ Sıklet: Hafif sıkletler hızlı ve dayanıklıdır, ağır sıkletler sert vurur ama çabuk yorulur.": "⚖️ Gewichtsklasse: Leichte Klassen sind schnell und zäh, Schwergewichte schlagen hart, ermüden aber schnell.",
  "🥋 Branş: En önemli seçim. Güçlü ve zayıf yönlerini, dolayısıyla nasıl dövüşeceğini belirler.": "🥋 Hintergrund: Die wichtigste Wahl. Sie bestimmt deine Stärken und Schwächen und damit, wie du kämpfst.",
  "📖 Hikâye: Kendin yazabilir ya da oyuna yazdırabilirsin.": "📖 Geschichte: Schreib sie selbst oder lass das Spiel sie schreiben.",
  "🎲 Zar: Son adımda istatistiklerin zarla belirlenir. Beğenmezsen 2 kez yeniden atabilirsin.": "🎲 Würfel: Im letzten Schritt werden deine Werte gewürfelt. Gefallen sie dir nicht? Du kannst zweimal neu würfeln.",
  "Gelişim Puanı": "Fähigkeitspunkte",
  "Kariyere 3 puanla başlarsın. Her antrenman kampı 1-3 puan verir (yoğunluk, yaş, kamp yeri, hoca ve kadro kalitesine bağlı). Kampın odak alanı ayrıca +1-3 gelişir.": "Du startest deine Karriere mit 3 Punkten. Jedes Trainingscamp bringt 1–3 Punkte (je nach Intensität, Alter, Camp-Ort, Trainer und Teamqualität). Der Fokusbereich des Camps verbessert sich außerdem um +1–3.",
  "Dövüşler de puan verir: galibiyet 2, bitiriş +1, bonus +1, kemer +1. Mağlubiyet ve beraberlik 1 puan.": "Auch Kämpfe bringen Punkte: Sieg 2, Finish +1, Bonus +1, Gürtel +1. Niederlage und Unentschieden 1 Punkt.",
  "📅 Bir dövüş döngüsü (kamp + toparlanma) yaklaşık 90-100 gün sürer. Yılda 3-4 kez dövüşürsün; her karar önemli.": "📅 Ein Kampfzyklus (Camp + Erholung) dauert etwa 90–100 Tage. Du kämpfst 3–4 Mal im Jahr; jede Entscheidung zählt.",
  "Puanı istediğin istatistiğe harcarsın. 50’ye kadar +1 için 1 puan, 70’e kadar 2, 85’e kadar 3, sonrası 4 puan gerekir.": "Gib Punkte für jeden beliebigen Wert aus. Bis 50 kostet +1 einen Punkt, bis 70 zwei, bis 85 drei, danach vier Punkte.",
  "Kamp sonunda tartıdan önce, dövüş sonrasında ya da Kariyer ekranındaki GELİŞİM sekmesinden harcayabilirsin.": "Du kannst sie vor dem Wiegen am Ende des Camps, nach einem Kampf oder im Tab ENTWICKLUNG auf dem Karrierebildschirm ausgeben.",
  "Nasıl Oynanır?": "So wird gespielt",
  "1️⃣ Rakip seç. Bölgesel aşamada sen seçersin, büyük organizasyonlarda rakibi organizasyon dayatır.": "1️⃣ Wähle einen Gegner. In der regionalen Stufe wählst du; in den großen Organisationen wird der Gegner zugeteilt.",
  "2️⃣ Kamp: odak alanı, oyun planı, yoğunluk, kilo verme ve basın toplantısı. Oyun planı rakibin zaafına denk gelirse kafeste büyük avantaj sağlar.": "2️⃣ Camp: Fokusbereich, Kampfplan, Intensität, Gewichtsschnitt und Pressekonferenz. Ein Kampfplan, der auf die Schwäche des Gegners zielt, bringt im Käfig einen großen Vorteil.",
  "3️⃣ Dövüş: her raunt taktik seçersin. Kritik anlarda (rakip sarsıldı, submission yakalandı) hızlı karar verirsin.": "3️⃣ Kampf: Wähle jede Runde eine Taktik. In kritischen Momenten (Gegner wackelt, Aufgabegriff sitzt) triffst du schnelle Entscheidungen.",
  "4️⃣ Sonrası: bonuslar, röportaj, sıralama, kontrat teklifleri ve dövüşler arası olaylar.": "4️⃣ Danach: Boni, Interview, Ranking, Vertragsangebote und Ereignisse zwischen den Kämpfen.",
  "🏆 Yol: Amatör → Bölgesel (CFC, Hexagon) → Büyük (PFC, ZEN, VIP) → DWCS veya kısa haber → UCC kemeri.": "🏆 Der Weg: Amateur → Regional (CFC, Hexagon) → Groß (PFC, ZEN, VIP) → DWCS oder kurzfristig → UCC-Gürtel.",
