  "Saat gece 02:14. Şehrin kenarında, tabelasının yarısı yanmayan bir spor salonu var.": "Es ist 2:14 Uhr nachts. Am Stadtrand steht ein Gym, dessen Schild zur Hälfte durchgebrannt ist.",
  "İçeride tek bir ampul yanıyor. Duvarda solmuş bir poster var: sekizgen bir kafes ve havaya kaldırılmış altın bir kemer.": "Drinnen brennt eine einzige Glühbirne. An der Wand ein verblasstes Poster: ein achteckiger Käfig und ein hochgehaltener goldener Gürtel.",
  "“Herkes kemeri ister. Pek azı yolu yürür.”": "„Jeder will den Gürtel. Wenige gehen den Weg.“",
