  "{0}. Tedavi olmazsan sağlığın her hafta düşer, dövüşte kondisyonun ve odağın zayıflar. Maç öncesi sağlık kontrolünde yakalanırsan maçın iptal edilir.": "{0}. Unbehandelt sinkt deine Gesundheit jede Woche, und Kondition und Konzentration leiden im Kampf. Wird es beim medizinischen Check vor dem Kampf entdeckt, wird dein Kampf abgesagt.",
