  "{0} sokaklarından çıktı, {1} yılda kemere uzandı. Sıradaki kim?": "Kam aus den Straßen von {0} und hat in {1} Jahren den Gürtel erreicht. Wer ist der Nächste?",
  "{0} karşısında: {1}.": "Gegen {0}: {1}.",
  "{0} sokaklarından çıktı; {1} yaşında {2} galibiyete ulaştı, {3} bitiriş.": "Kam aus den Straßen von {0}; mit {1} Jahren {2} Siege und {3} Finishes.",
  "HOCAN · {0}": "DEIN TRAINER · {0}",
  "ANLADIM": "VERSTANDEN",
  "İpuçlarını kapat": "Tipps ausschalten",
  "Burası senin köşen": "Das ist deine Ecke",
  "Üstte paran, sağlığın ve popülerliğin var. Hazır olduğunda “DÖVÜŞ AYARLA” ile rakibini seç. Aradaki haftalarda mağaza, sosyal medya ve gece hayatı seni bekliyor; ama unutma, her şeyin bir bedeli var.": "Oben siehst du Geld, Gesundheit und Popularität. Wenn du bereit bist, wähle mit „KAMPF ANSETZEN“ deinen Gegner. In den Wochen dazwischen warten Shop, soziale Medien und Nachtleben; aber denk dran, alles hat seinen Preis.",
  "Gelişim puanları": "Fähigkeitspunkte",
  "Kamplardan ve dövüşlerden puan kazanırsın, burada istatistiklerine dağıtırsın. 50’den sonra her artış pahalanır; zayıf yönünü kapatmak çoğu zaman daha akıllıcadır.": "Punkte bekommst du aus Camps und Kämpfen und gibst sie hier für deine Werte aus. Über 50 wird jeder Punkt teurer; deine Schwäche auszugleichen ist meist klüger.",
  "Rakibini seç": "Wähle deinen Gegner",
  "Her rakibin gücü ve zayıf yönü yazıyor. Kolay rakip güvenlidir ama az kazandırır; riskli bir rakibi yenersen sıralamada büyük bir sıçrama yaparsın.": "Stärke und Schwäche jedes Gegners sind aufgeführt. Ein leichter Gegner ist sicher, bringt aber wenig; schlägst du einen riskanten, machst du einen großen Sprung im Ranking.",
  "Kamp başlıyor": "Das Camp beginnt",
  "Önce kampın süresini seç. Uzun kamp daha çok geliştirir ama pahalıdır ve yorar. Kamptan önceki boş haftalarda teknik çalışabilir, spar yapabilirsin.": "Wähle zuerst, wie lang dein Camp ist. Ein langes Camp entwickelt dich mehr, kostet aber mehr und laugt dich aus. In den freien Wochen vor dem Camp kannst du Technik üben und sparren.",
  "Oyun planı": "Kampfplan",
  "Rakibin zayıf yönüne uyan plan, dövüşte etkisini ikiye katlar. Keşif raporuna bak ve planını ona göre seç.": "Ein Plan, der zur Schwäche deines Gegners passt, wirkt im Kampf doppelt. Schau dir den Scouting-Bericht an und wähle deinen Plan danach.",
  "Burun buruna": "Auge in Auge",
  "Tartıdan sonra rakibinle yüz yüze geleceksin. Takındığın tavır onun moralini bozabilir ya da sana pahalıya patlayabilir.": "Nach dem Wiegen stehst du deinem Gegner Auge in Auge gegenüber. Deine Haltung kann seinen Willen brechen oder dich teuer zu stehen kommen.",
  "Her raundun başında bir taktik seç, dövüş kendi akar. Rakip sarsıldığında ya da bir submission fırsatında hızlı karar vermen gerekir. Kondisyonunu izle: yorulursan her şey zorlaşır.": "Wähle zu Beginn jeder Runde eine Taktik, dann läuft der Kampf von selbst. Wackelt dein Gegner oder bietet sich ein Aufgabegriff, musst du schnell entscheiden. Achte auf deine Kondition: Bist du müde, wird alles schwerer.",
  "Dövüş bitti": "Der Kampf ist vorbei",
  "Mikrofon sende: röportajdaki sözlerin popülerliğini etkiler. Kazandığın puanları GELİŞİM sekmesinde harca. Güzel bir galibiyet mi? Paylaş, herkes görsün!": "Das Mikro gehört dir: Was du im Interview sagst, beeinflusst deine Popularität. Gib die verdienten Punkte im Tab ENTWICKLUNG aus. Ein toller Sieg? Teil ihn, damit alle ihn sehen!",
