  "Bugün kafeste daha iyi olan kazandı. Saygılar {0}. Bu rekabet beni daha iyi bir dövüşçü yaptı.": "Heute hat der bessere Kämpfer gewonnen. Respekt, {0}. Diese Rivalität hat mich zu einem besseren Kämpfer gemacht.",
