  "{0} sessizce salondan ayrıldı ve bir rakibinin kampına geçti. Oyun planlarını, zayıf yönlerini, her şeyi anlatıyor olabilir.": "{0} hat still und leise das Gym verlassen und sich dem Camp eines Rivalen angeschlossen. Er könnte deine Kampfpläne, deine Schwächen, einfach alles ausplaudern.",
  "Kampı baştan kur ({0})": "Camp neu aufbauen ({0})",
  "Basına anlat": "An die Presse gehen",
  "Önemseme": "Ignorieren",
  "Yeni bir sistem kurdun, bütün kombinasyonları değiştirdin. Masraflı ama sürpriz yine sende: IQ +1.": "Du hast ein neues System aufgebaut und jede Kombination geändert. Teuer, aber die Überraschung liegt weiter bei dir: IQ +1.",
  "📰 İhanet: {0}, {1} ile yollarını ayırıp rakip kampa geçti.": "📰 Verrat: {0} hat sich von {1} getrennt und ist zu einem rivalisierenden Camp gewechselt.",
  "Hikâyeni herkes konuştu. Taraftar senin yanında: popülerlik +3.": "Alle reden über deine Geschichte. Die Fans stehen auf deiner Seite: Popularität +3.",
  "Önemsemedin; bu öfkeyi antrenmana taşıdın. Sonraki kampta motivasyon +1.": "Du hast es ignoriert und die Wut ins Training mitgenommen. Motivation +1 im nächsten Camp.",
  "📱 Bir Özür Mesajı": "📱 Eine Entschuldigung",
  "{0} yazdı: “Hata yaptım. O kampta anlatılanların hepsi boş çıktı. Geri dönebilir miyim?”": "{0} schrieb: „Ich habe einen Fehler gemacht. Alles, was sie mir in dem Camp versprochen haben, war leer. Darf ich zurückkommen?“",
  "Affet, geri al": "Verzeihen, zurücknehmen",
  "Kapıyı kapat": "Die Tür schließen",
  "{0} geri döndü ve eskisinden sıkı çalışıyor. Kondisyon +1.": "{0} ist zurück und arbeitet härter als je zuvor. Kondition +1.",
  "“Sadakat her şeydir.” Cevabın kısa ve netti. Popülerlik +1.": "„Loyalität ist alles.“ Deine Antwort war kurz und klar. Popularität +1.",
  "🏥 Kritik Karar": "🏥 Eine kritische Entscheidung",
  "{0} ciddi görünüyor ({1} hafta). Doktorun iki yol sunuyor: ameliyat ya da uzun fizik tedavi. Hocan ise “ağrı kesiciyle devam, zaman kaybetme” diyor.": "{0} sieht ernst aus ({1} Wochen). Dein Arzt bietet zwei Wege an: Operation oder lange Physiotherapie. Dein Trainer sagt: „Nimm Schmerzmittel und mach weiter, verschwende keine Zeit.“",
  "Ameliyat ({0})": "Operation ({0})",
  "Fizik tedavi ({0})": "Physiotherapie ({0})",
  "Ağrı kesiciyle devam": "Mit Schmerzmitteln weitermachen",
  "Sakatlık kendiliğinden toparlandı.": "Die Verletzung ist von selbst verheilt.",
  "Ameliyat başarılı geçti. İyileşme {0} hafta kısaldı.": "Die Operation ist gut verlaufen. Die Erholung ist {0} Wochen kürzer.",
  "Uzun ve sabır isteyen bir süreç başladı. İyileşme 2 hafta kısaldı.": "Ein langer Prozess, der Geduld braucht, hat begonnen. Die Erholung ist 2 Wochen kürzer.",
  "Ağrıyı bastırıp devam ettin. Hemen kafese dönebilirsin ama {0} kalıcı olarak -2.": "Du hast den Schmerz betäubt und weitergemacht. Du kannst sofort zurück in den Käfig, aber {0} ist dauerhaft -2.",
  "🔥 Geri Dönüş Hikâyesi": "🔥 Eine Comeback-Geschichte",
  "Sakatlıktan sonraki ilk galibiyetin manşetlerde: “Bitti denilen dövüşçü geri döndü!” Mikrofonlar sende.": "Dein erster Sieg nach der Verletzung steht in den Schlagzeilen: „Der Abgeschriebene ist zurück!“ Das Mikro gehört dir.",
  "Ekibine teşekkür et": "Danke deinem Team",
  "Eleştirenlere cevap ver": "Antworte den Kritikern",
  "🌧️ Zor Dönüş": "🌧️ Eine schwere Rückkehr",
  "Sakatlık sonrası dönüş istediğin gibi olmadı. Bazıları “eskisi gibi değil” diyor. {0}": "Das Comeback lief nicht wie gewünscht. Manche sagen: „Er ist nicht mehr der Alte.“ {0}",
  "Ağrı kesicilerle geçen haftaların bedeli ağır.": "Die Wochen mit Schmerzmitteln fordern ihren Tribut.",
  "Daha çok çalış": "Noch härter arbeiten",
  "Kendine zaman tanı": "Dir Zeit geben",
  "Ekibinle kucaklaştığın fotoğraf haftanın en çok paylaşılanı oldu. Motivasyon +1.": "Das Foto, wie du dein Team umarmst, war das meistgeteilte der Woche. Motivation +1.",
  "Sözlerin manşet oldu. Popülerlik +4.": "Deine Worte haben Schlagzeilen gemacht. Popularität +4.",
  "Sert çıkışın ters tepti; kibirli bulundun. Popülerlik -2.": "Deine harte Antwort ging nach hinten los; du wirktest arrogant. Popularität -2.",
  "Salona herkesten önce gelip en son çıkıyorsun. +1 gelişim puanı.": "Du bist als Erster im Gym und gehst als Letzter. +1 Fähigkeitspunkt.",
  "Birkaç hafta aileyle, telefonsuz. Vücudun toparlandı: sağlık +20.": "Ein paar Wochen mit der Familie, ohne Handy. Dein Körper hat sich erholt: Gesundheit +20.",
  "🧾 Muhasebeci Uyarıyor": "🧾 Die Warnung des Buchhalters",
  "Muhasebecin hesaplarda tutmayan rakamlar buldu. Menajerin {0} bazı ödemeleri kendi şirketi üzerinden geçiriyor olabilir.": "Dein Buchhalter hat Zahlen gefunden, die nicht stimmen. Dein Manager {0} leitet womöglich Zahlungen über seine eigene Firma.",
