  "Menajerime güveniyorum": "Ich vertraue meinem Manager",
  "Bir mali müşavir tuttun. Sonuçlar birkaç hafta içinde gelecek.": "Du hast einen Wirtschaftsprüfer beauftragt. Die Ergebnisse kommen in ein paar Wochen.",
  "Menajerine güvenmeyi seçtin. Muhasebeci omuz silkti.": "Du hast dich entschieden, deinem Manager zu vertrauen. Der Buchhalter hat mit den Schultern gezuckt.",
