  "Ders pahalıya patladı: -{0}. Artık menajerin yok.": "Eine teure Lektion: -{0}. Du hast keinen Manager mehr.",
  "Mahkeme senden yana karar verdi: {0} geri geldi. Hikâyen herkese örnek oldu. Popülerlik +2.": "Das Gericht gab dir recht: {0} kamen zurück. Deine Geschichte wurde für alle zum Beispiel. Popularität +2.",
  "Sessiz bir anlaşma: {0} geri aldın ve yollarını ayırdın.": "Eine stille Einigung: Du hast {0} zurückbekommen und euch getrennt.",
  "Affettin. Menajerin minnettar ama ekipte bir şey kırıldı. Motivasyon -1.": "Du hast verziehen. Dein Manager ist dankbar, aber im Team ist etwas zerbrochen. Motivation -1.",
  "🥊 Babanın Hayali": "🥊 Der Traum deines Vaters",
  "Baban gençliğinde amatör boksörmüş. Şimdi 58 yaşında, bir yardım gecesinde son bir kez ringe çıkmak istiyor. Senden destek bekliyor.": "Dein Vater war in seiner Jugend Amateurboxer. Jetzt ist er 58 und will bei einem Benefizabend ein letztes Mal in den Ring steigen. Er hofft auf deine Unterstützung.",
  "Destekle, onu çalıştır": "Unterstützen, ihn trainieren",
  "Vazgeçirmeye çalış": "Versuchen, es ihm auszureden",
  "Sabah koşularına artık baban da geliyor. Salonda herkes ona “Usta” diyor. Motivasyon +1.": "Dein Vater läuft jetzt morgens mit dir. Alle im Gym nennen ihn „Meister“. Motivation +1.",
  "Ona riskleri anlattın. Sessizce dinledi, bir şey demedi.": "Du hast ihm die Risiken erklärt. Er hat still zugehört und nichts gesagt.",
  "💔 Kırgın Bir Baba": "💔 Ein gekränkter Vater",
  "Baban yardım gecesine çıkmadı ama sana kırgın: “Sen kendi yolunu seçtin, ben de bir kez seçmek istemiştim.”": "Dein Vater hat beim Benefizabend nicht gekämpft, aber er ist gekränkt: „Du hast deinen Weg gewählt. Ich wollte nur einmal meinen wählen.“",
  "Özür dile, onu bir sonraki maçına davet et": "Entschuldigen und ihn zu deinem nächsten Kampf einladen",
  "Zamanla geçer": "Das vergeht mit der Zeit",
  "🎉 Babanın Gecesi": "🎉 Der Abend deines Vaters",
  "Baban üç raunt boyunca dimdik durdu ve salon ayağa kalktı! Onu ringte kucakladığın video her yerde.": "Dein Vater hat drei Runden lang standgehalten und die ganze Halle ist aufgestanden! Das Video, wie du ihn im Ring umarmst, ist überall.",
  "Onunla gurur duy": "Sei stolz auf ihn",
  "🏥 Zor Bir Gece": "🏥 Eine schwere Nacht",
  "Baban ikinci rauntta düştü. İyi, ama bir gece hastanede kalacak. Masraflar {0}.": "Dein Vater ging in der zweiten Runde zu Boden. Es geht ihm gut, aber er bleibt eine Nacht im Krankenhaus. Die Rechnungen belaufen sich auf {0}.",
  "Yanında ol": "Bleib an seiner Seite",
  "Maç gecesi baban ilk sıradaydı. Aranızdaki buz eridi. Motivasyon +1.": "Am Kampfabend saß dein Vater in der ersten Reihe. Das Eis zwischen euch ist geschmolzen. Motivation +1.",
  "Aranızdaki mesafe büyüdü. Motivasyon -1.": "Die Distanz zwischen euch ist gewachsen. Motivation -1.",
  "Baba-evlat hikâyesi herkesin yüreğine dokundu. Popülerlik +4, motivasyon +1.": "Die Geschichte von Vater und Kind hat alle berührt. Popularität +4, Motivation +1.",
  "Sabaha kadar yanındaydın. Taburcu olurken gülümsedi: “Değdi.” Motivasyon +1.": "Du bist bis zum Morgen bei ihm geblieben. Bei der Entlassung lächelte er: „Es hat sich gelohnt.“ Motivation +1.",
  "YOL: Kafesten Kemere · {0} {1} kariyer kodu (Menü → Kariyer içe aktar):": "YOL: Vom Käfig zum Gürtel · Karrierecode von {0} {1} (Menü → Karriere importieren):",
