  "Kod okunamadı. Tamamını kopyaladığından emin ol.": "Der Code konnte nicht gelesen werden. Stell sicher, dass du ihn vollständig kopiert hast.",
  "Boş yuva yok. Önce bir kariyeri sil ya da yuvaları artır.": "Kein freier Slot. Lösch erst eine Karriere oder schalte mehr Slots frei.",
