  "KARİYERİ TAŞI": "KARRIERE ÜBERTRAGEN",
  "Eski cihazında yuvanın yanındaki dışa aktar düğmesiyle kariyer kodunu al, buraya yapıştır. Kariyer ilk boş yuvaya eklenir.": "Hol dir auf deinem alten Gerät mit dem Export-Button neben dem Slot den Karrierecode und füg ihn hier ein. Die Karriere kommt in den ersten freien Slot.",
