  "Bu ekran açılırken bir hata oluştu. Kariyerin güvende: menüye dönüp devam edebilirsin. Sorun sürerse son sağlam kayda dön.": "Beim Öffnen dieses Bildschirms ist ein Fehler aufgetreten. Deine Karriere ist sicher: Geh zurück ins Menü und spiel weiter. Bleibt das Problem, kehr zum letzten guten Speicherstand zurück.",
