  "İpucu: Hakarete espriyle, övünmeye sert, alaya soğukkanlı cevap ver.": "Tipp: Kontere Beleidigungen mit Humor, Prahlerei mit Feuer, Spott mit Eiseskälte.",
  "{0} mi? Bu kafese değil, kreşe gitmeli.": "{0}? Der gehört in die Kita, nicht in den Käfig.",
  "Şu surata bakın: daha önce çok dayak yediği belli.": "Schau dir das Gesicht an. Man sieht, dass es schon viele Prügel eingesteckt hat.",
  "Onun antrenmanlarını izledim. Annem daha sert vuruyor.": "Ich hab die Trainingsvideos gesehen. Meine Mutter schlägt härter.",
  "Tek yeteneği basın toplantısında uyumamak.": "Das einzige Talent hier ist, bei Pressekonferenzen wach zu bleiben.",
  "Ben bu sıkletin kralıyım. Onu ilk rauntta uyutacağım, yazın bir kenara.": "Ich bin der König dieser Gewichtsklasse. Licht aus in Runde eins, schreib's dir auf.",
  "Bana rakip bulamıyorlar, o yüzden bunu getirdiler.": "Sie finden keine echten Gegner für mich, also haben sie den hier gebracht.",
  "Kemeri şimdiden evime astım. Bu maç sadece formalite.": "Der Gürtel hängt schon bei mir zu Hause. Dieser Kampf ist eine Formsache.",
  "Benim ısınmam onun bütün kariyeri kadar sürüyor.": "Mein Aufwärmen dauert länger als diese ganze Karriere.",
  "Hahaha! {0} titriyor bakın, ellerine bakın!": "Hahaha! {0} zittert, schaut euch die Hände an!",
  "Kilo verirken ağladığını duydum. Çok tatlı.": "Hab vom Heulen beim Gewichtmachen gehört. Wie süß.",
  "Gözlerime bakamıyor bile. Daha şimdiden kaybetti.": "Kann mir nicht mal in die Augen schauen. Schon verloren.",
  "Hocası bile onun yerine utanıyor, şu hâline bakın.": "Sogar der Trainer schämt sich. Schaut euch das an.",
  "Kreş mi? Doğru, cumartesi seni orada bebek gibi uyutacağım.": "Kita? Klar, am Samstag schläferst du ein wie ein Baby.",
  "Annenle antrenman yapıyorsan bana da numarasını ver, belki bir şey öğrenirim.": "Wenn du mit deiner Mutter trainierst, gib mir ihre Nummer. Vielleicht lerne ich was.",
  "Konuş, konuş. Cumartesi gecesi konuşamayacaksın.": "Red ruhig weiter. Samstagnacht kannst du das nicht mehr.",
  "Laflar ucuz. Kafeste görüşürüz.": "Reden ist billig. Wir sehen uns im Käfig.",
  "Bir daha ağzını açarsan burada dağıtırım seni!": "Mach noch einmal den Mund auf und ich mach dich hier fertig!",
  "Kapa çeneni yoksa ben kapatırım!": "Halt den Mund oder ich halt ihn dir zu!",
  "Kral mı? Son üç maçında yere kaç kez düştüğünü sayalım mı?": "König? Wollen wir zählen, wie oft du in deinen letzten drei Kämpfen am Boden lagst?",
  "Kemeri evine asmışsın, güzel. Ben gelip alacağım.": "Der Gürtel hängt an deiner Wand? Gut. Ich komm ihn holen.",
  "İlk rauntta uyutacakmış… herhalde bu konuşmasıyla.": "Licht aus in Runde eins… mit dieser Rede vielleicht.",
  "Tamam. Görürüz.": "Okay. Wir werden sehen.",
  "Saygı duyuyorum, iyi şanslar.": "Respekt. Viel Glück.",
  "Gülmeye devam et. Son gülen iyi güler.": "Lach ruhig weiter. Wer zuletzt lacht, lacht am besten.",
  "Ellerim titremiyor, sadece seni beklemekten sıkıldılar.": "Meine Hände zittern nicht. Sie langweilen sich nur, weil sie auf dich warten.",
  "Gülüyor musun? Cumartesi gülemeyeceksin!": "Du lachst? Am Samstag lachst du nicht mehr!",
  "Bir daha bana gülersen sahnede kavga çıkar!": "Lach noch einmal über mich und es gibt gleich hier auf der Bühne eine Schlägerei!",
  "Hahaha, evet çok komiksin… dur, bunu anneme de anlatayım.": "Hahaha, ja, du bist echt witzig… Moment, ich erzähl's meiner Mutter.",
  "Titriyorum çünkü burası çok soğuk, senin kariyerin gibi.": "Ich zittere, weil es hier kalt ist, genau wie deine Karriere.",
