  "🎤 Basın toplantısında laflar havada uçuştu, kimse üstün gelemedi. Popülerlik +2. {0} gaza geldi.": "🎤 Bei der Pressekonferenz flogen die Worte, aber keiner hat gewonnen. Popularität +2. {0} ist angestachelt.",
  "🎤 Basın toplantısını sen kazandın! Video milyonlarca izlendi. {0}. {1} sinirden ne dediğini bilmiyordu (rakip IQ -2).": "🎤 Du hast die Pressekonferenz gewonnen! Der Clip hat Millionen Aufrufe. {0}. {1} war so verunsichert, dass kein klarer Gedanke mehr möglich war (Gegner-IQ -2).",
  "Basın toplantısında rakiple canlı laf düellosuna gir. Kazanırsan popülerlik patlar, kaybedersen alay konusu olursun.": "Liefert euch auf der Pressekonferenz ein Live-Trash-Talk-Duell. Gewinnst du, explodiert deine Popularität; verlierst du, wirst du zum Meme.",
