  "Dünya turu": "Welttournee",
  "Her maç bir şehirde. Yeni şehirler ve kıtalar kilometre taşı ödülleri getirir.": "Jeder Kampf findet in einer Stadt statt. Neue Städte und Kontinente schalten Meilenstein-Belohnungen frei.",
