  "Halka altın olunca KAÇ, sonra hemen vur. DİREKT ve TEKME saldırı hazırlığını keser.": "Wenn der Ring golden wird, AUSWEICHEN, dann sofort zuschlagen. CROSS und KICK unterbrechen ein Ausholen.",
