  "TAP ATTIN": "DU HAST ABGEKLOPFT",
  "🔒 ya da ⤴️ görünce KONTROL. Rakip yorulunca SUB dene.": "Siehst du 🔒 oder ⤴️? Drück KONTROLLE. Geh auf den SUB, sobald er müde ist.",
  "🔒 görünce hemen KURTUL. 👊 gelirken GARD al.": "Siehst du 🔒? Sofort BEFREIEN. DECKUNG hoch, wenn 👊 kommt.",
  "Halka altın olunca KAÇ (⬇️ takedown'a karşı da). DİREKT ve TEKME hazırlığı keser.": "Wenn der Ring golden wird, AUSWEICHEN (wirkt auch gegen ⬇️ Takedowns). CROSS und KICK unterbrechen ein Ausholen.",
  "🤼 Yerde kontrol: {0} sn – {1} sn": "🤼 Bodenkontrolle: {0}s – {1}s",
  "🔒 TAP! {0} kilidin içinde tap attı. Submission!": "🔒 ABGEKLOPFT! {0} hat im Griff abgeklopft. Aufgabe!",
  "🔒 Kilitten çıkamadın… tap attın.": "🔒 Du bist nicht aus dem Griff gekommen… du hast abgeklopft.",
