  "Rakibi oku": "Lies deinen Gegner",
  "Rakip saldırı hazırlarken başında küçülen bir halka çıkar. Halka ALTIN olunca KAÇ'a bas, sonra hemen vur: kontra vuruşların çift hasar yapar.": "Wenn dein Gegner ausholt, erscheint ein schrumpfender Ring um seinen Kopf. Wird der Ring GOLDEN, drück AUSWEICHEN und schlag sofort zu: Konter machen doppelten Schaden.",
  "Vur ve kes": "Schlagen und unterbrechen",
  "JAB hızlı ve ucuz, DİREKT ve TEKME ağırdır. Rakip hazırlanırken DİREKT ya da TEKME atarsan saldırısını kesersin. Sarı çubuk nefesin: bitince vuruşların zayıflar.": "JAB ist schnell und kostet wenig, CROSS und KICK sind schwer. Wirf während seines Ausholens einen CROSS oder KICK, um ihn zu unterbrechen. Der gelbe Balken ist deine Ausdauer: Ist sie leer, werden deine Schläge schwach.",
  "İNDİR ile takedown dene; rakip ⬇️ ile dalarsa KAÇ ile sprawl yap. Yerde düğmeler değişir: üstteyken vur ve submission ara, alttayken 🔒 görünce hemen KURTUL.": "Versuch einen TAKEDOWN; schießt er mit ⬇️, sprawle mit AUSWEICHEN. Am Boden ändern sich die Buttons: Oben schlägst du und suchst die Aufgabe; unten BEFREIST du dich, sobald du 🔒 siehst.",
  "DURAKLATILDI": "PAUSIERT",
  "Devam et": "Weiter",
  "Anladım, dövüşelim!": "Verstanden, kämpfen wir!",
