  "İlk maçına çık": "Bestreite deinen ersten Kampf",
  "\"Dövüş ayarla\" ile rakibini seç.": "Wähl deinen Gegner mit „Kampf ansetzen“.",
  "Gelişim puanı harca": "Gib einen Fortschrittspunkt aus",
  "\"Gelişim\" sekmesinde bir istatistiği yükselt.": "Steigere einen Wert im Tab „Fortschritt“.",
  "Mağazadan bir şey al": "Kauf etwas im Shop",
  "Ekipman maçta küçük avantaj sağlar.": "Ausrüstung gibt einen kleinen Vorteil im Kampf.",
  "Sosyal medyada paylaş": "Poste in den sozialen Medien",
  "Takipçi para ve sponsor getirir.": "Follower bringen Geld und Sponsoren.",
  "Amatörde 3 galibiyet al, teklifler gelsin.": "Gewinne 3 Amateurkämpfe und die Angebote kommen.",
  "✅ {0}: +${1}, {2} takipçi.": "✅ {0}: +{1} $, {2} Follower.",
  "İLK ADIMLAR": "ERSTE SCHRITTE",
  "Üstte paran, sağlığın ve popülerliğin var. Hazır olduğunda “DÖVÜŞ AYARLA” ile rakibini seç. “İlk adımlar” sana yol gösterecek; maç yaptıkça yeni şeyler açılacak. Ama unutma, her şeyin bir bedeli var.": "Oben siehst du Geld, Gesundheit und Popularität. Wenn du bereit bist, wähl deinen Gegner mit „KAMPF ANSETZEN“. „Erste Schritte“ führt dich; mit jedem Kampf wird mehr freigeschaltet. Aber denk dran: Alles hat seinen Preis.",
