  "Bas ya da basılı tut. DİREN! yanınca yeniden bas ve bırakma!": "Tippen oder halten. Leuchtet WIDERSTEHEN! auf, drück erneut und lass nicht los!",
  "Çubuk dolarsa tap atarsın! Bas ya da basılı tut, kurtul!": "Ist der Balken voll, klopfst du ab! Tippen oder halten zum Befreien!",
  "DİREN!": "WIDERSTEHEN!",
  "⚖️ Kilonu tartıdan önceki son 48 saatte kendin vereceksin. Bu organizasyonda hidrasyon testi var: kendini kurutma.": "⚖️ Du machst dein Gewicht in den letzten 48 Stunden vor dem Wiegen selbst. Diese Organisation macht einen Hydrationstest: Trockne dich nicht aus.",
  "⚖️ Kilonu tartıdan önceki son 48 saatte kendin vereceksin. Su kesimini iyi yönetirsen kafese rakibinden iri çıkarsın.": "⚖️ Du machst dein Gewicht in den letzten 48 Stunden vor dem Wiegen selbst. Mach den Wasser-Cut gut und du gehst größer als dein Gegner in den Kampf.",
  "Son 48 saat: kilonu ver": "Letzte 48 Stunden: Gewicht machen",
  "🏆 Yükseliş Grand Prix'i daveti geldi! 8 amatör, tek kupa: şampiyon ve finalist profesyonel kapıyı açar.": "🏆 Einladung zum Nachwuchs-Grand-Prix! 8 Amateure, eine Trophäe: Champion und Finalist öffnen die Tür zu den Profis.",
  "🏆 Yükseliş Grand Prix'ine katıldın: 8 amatör, üç maç. Profesyonel organizasyonlar izliyor.": "🏆 Du bist im Nachwuchs-Grand-Prix: 8 Amateure, drei Kämpfe. Die Profi-Organisationen schauen zu.",
  "Yükseliş Grand Prix'i Şampiyonu ({0})": "Nachwuchs-Grand-Prix-Champion ({0})",
  "🏆 Yükseliş Grand Prix'ini kazandın! Organizasyonlar sıraya girdi: profesyonel kapı ardına kadar açık.": "🏆 Du hast den Nachwuchs-Grand-Prix gewonnen! Die Organisationen stehen Schlange: Die Profitür steht weit offen.",
  "🥈 Finalde kaybettin ama herkes seni izledi. Profesyonel organizasyonlar seni kadrosunda istiyor!": "🥈 Du hast das Finale verloren, aber alle haben zugeschaut. Die Profi-Organisationen wollen dich im Kader!",
  "YÜKSELİŞ GRAND PRIX'İ DAVETİ": "EINLADUNG ZUM NACHWUCHS-GRAND-PRIX",
  "Profesyonelliğe giden yolda vitrin: 8 amatör, üç maç (çeyrek final, yarı final, final). Kaybeden elenir. Şampiyon {0} ve kupayı alır; şampiyon da finalist de doğrudan profesyonel teklif alır. Davet yalnızca bir kez gelir.": "Dein Schaufenster auf dem Weg zu den Profis: 8 Amateure, drei Kämpfe (Viertelfinale, Halbfinale, Finale). Wer verliert, ist raus. Der Champion bekommt {0} und die Trophäe; Champion und Finalist erhalten direkte Profiangebote. Diese Einladung kommt nur einmal.",
  "YÜKSELİŞ GRAND PRIX'İ": "NACHWUCHS-GRAND-PRIX",
  "YÜKSELİŞ GRAND PRIX DAVETİ": "EINLADUNG ZUM NACHWUCHS-GRAND-PRIX",
