  "Alev desenli şort, ateş eldiveni, Ejderha çerçevesi ve kemeri, kafese ATEŞ efektiyle giriş": "Shorts mit Flammenmuster, Feuerhandschuhe, Drachen-Rahmen und -Gürtel, Einlauf mit FEUER-Effekt",
  "Şimşek desenli buz şortu, buz eldiveni, Buz Kralı çerçevesi ve kemeri, kafese KAR FIRTINASI ile giriş": "Eis-Shorts mit Blitzmuster, Eishandschuhe, Eiskönig-Rahmen und -Gürtel, Einlauf im SCHNEESTURM",
  "Yıldız desenli mor şort, mor neon eldiven, Gece Yarısı çerçevesi ve kemeri, ŞİMŞEK giriş efekti": "Lila Shorts mit Sternenmuster, Neon-Lila-Handschuhe, Mitternacht-Rahmen und -Gürtel, BLITZ-Einlaufeffekt",
  "TAM SÜRÜM": "VOLLVERSION",
  "Oyunun tamamı ücretsiz kalır. Tam sürüm tek seferlik alınır, abonelik yoktur.": "Das ganze Spiel bleibt kostenlos. Die Vollversion ist ein einmaliger Kauf, kein Abo.",
  "Altın Seri kozmetik paketi ve Şampiyon çerçevesi": "Kosmetikpaket Gold-Serie und Champion-Rahmen",
  "Reklamsız oynamak ister misin?": "Willst du ohne Werbung spielen?",
  "Tam Sürüm tek seferlik: reklamlar kalkar, ödüller anında gelir, 5 kariyer yuvası ve Altın Seri.": "Vollversion, einmalig: keine Werbung, sofortige Belohnungen, 5 Karriere-Slots und die Gold-Serie.",
  "Tam Sürüm · {0}": "Vollversion · {0}",
  "Tam Sürüm": "Vollversion",
