  "Bir saat konuştunuz. Sonunda “Tamam abi” dedi. Ne kadar sürer, bilinmez.": "Ihr habt eine Stunde geredet. Am Ende sagte er: „Okay, großer Bruder.“ Wer weiß, wie lange es hält.",
