  "Henüz kartpostal yok. Mağaza › Tatil'den bir yere git, dönüşte kartpostalın burada olsun.": "Noch keine Postkarten. Mach eine Reise über Shop › Urlaub, dann liegt deine Postkarte hier, wenn du zurück bist.",
  "Aile albümü boş. Evlilik, çocukların ve onların ilk anları burada birikir.": "Das Familienalbum ist leer. Hochzeit, deine Kinder und ihre ersten Male sammeln sich hier.",
  "NOT": "HINWEIS",
  "Hatıralar yalnızca anıdır; güç vermez. Evindeki duvarlarda da görünürler.": "Erinnerungsstücke sind nur Erinnerungen; sie geben keine Stärke. Sie erscheinen auch an den Wänden deines Zuhauses.",
