  "Nadir saatler, klasik arabalar ve sanat eserleri. Değerleri her hafta değişir; doğru zamanda al, doğru zamanda sat.": "Seltene Uhren, Oldtimer und Kunst. Ihr Wert ändert sich jede Woche; kauf zur richtigen Zeit, verkauf zur richtigen Zeit.",
