  "Düşüşte · {0}": "In der Krise · {0}",
  "🌍 Eski rakibin {0}, şampiyon olarak eldivenlerini astı.": "🌍 Dein alter Rivale {0} hat als Champion aufgehört.",
  "🌍 Bir zamanlar yendiğin {0} emekli oldu.": "🌍 {0}, den du einst geschlagen hast, hat aufgehört.",
  "🌍 Yendiğin {0} toparlandı: {1} maçtır kazanıyor.": "🌍 {0}, den du geschlagen hast, ist zurück: {1} Siege in Folge.",
  "🌍 {0} senden sonra bir türlü toparlanamadı, üst üste kaybediyor.": "🌍 {0} hat sich von der Niederlage gegen dich nie erholt und verliert weiter.",
  "🌍 Bir zamanlar yendiğin {0}, {1} ile sözleşme imzaladı!": "🌍 {0}, den du einst geschlagen hast, hat gerade bei {1} unterschrieben!",
  "🌍 Yendiğin {0}, {1} şampiyonu oldu!": "🌍 {0}, den du geschlagen hast, wurde {1}-Champion!",
  "🌍 {0}, {1} sahnesinde zorlanıyor.": "🌍 {0} tut sich auf der Bühne von {1} schwer.",
  "🌍 {0}, {1} kemerini kaybetti.": "🌍 {0} hat den {1}-Gürtel verloren.",
  "Albümündeki kartı altına yükseldi.": "Seine Karte in deinem Album ist jetzt golden.",
  "Rıza Hoca": "Trainer Rıza",
  "Coach Marcus Bell": "Trainer Marcus Bell",
  "Sergei Volkov": "Sergei Volkov",
  "Mestre Paulo Reis": "Mestre Paulo Reis",
  "Kenji Arakawa": "Kenji Arakawa",
  "Duncan McRae": "Duncan McRae",
  "Baba-evlat gibi": "Wie Familie",
  "Sıkı bağ": "Starke Bindung",
  "İyi gidiyor": "Läuft gut",
  "Kopma noktasında": "Kurz vor dem Bruch",
  "🤝 {0} ile aranız çok iyi: köşedeki her sözü tam zamanında geliyor (IQ +1).": "🤝 Du und {0} seid im Einklang: Jedes Wort aus der Ecke kommt genau zur rechten Zeit (IQ +1).",
  "🧊 {0} ile aranız soğuk: köşede konuşmalar kısa ve gergin (IQ -1).": "🧊 Zwischen dir und {0} herrscht Eiszeit: Die Ansagen in der Ecke sind kurz und angespannt (IQ -1).",
  "{0}: “Seninle gurur duyuyorum. Şimdi git ve al şunu.”": "{0}: „Ich bin stolz auf dich. Jetzt geh und hol ihn dir.“",
  "{0} yalnızca “Planı biliyorsun.” dedi. Sesi soğuktu.": "{0} sagte nur: „Du kennst den Plan.“ Seine Stimme war kalt.",
  "💢 Hocanla Kriz": "💢 Krise mit deinem Trainer",
  "{0} antrenmandan sonra seni kenara çekti: “Beni dinlemiyorsun. Böyle devam edeceksek yollarımızı ayıralım.”": "Nach dem Training nahm dich {0} beiseite: „Du hörst nicht auf mich. Wenn das so weitergeht, sollten wir uns trennen.“",
  "Özür dile, yeniden başlayalım": "Entschuldigen und neu anfangen",
  "Maaşına zam yap ({0})": "Ihm eine Gehaltserhöhung geben ({0})",
  "Yollarınızı ayırın": "Trennen",
  "Gururunu yuttun. {0} başını salladı: “Yarın sabah altıda.” Bağ toparlanıyor, motivasyon -1.": "Du hast deinen Stolz runtergeschluckt. {0} nickte: „Morgen um sechs.“ Die Bindung heilt, Motivation -1.",
  "Zam iyi geldi ama asıl önemli olan oturup konuşmanızdı. Bağ güçlendi.": "Die Gehaltserhöhung hat geholfen, aber was wirklich zählte, war das Gespräch. Die Bindung ist stärker.",
  "{0} ile yollarınız ayrıldı. Yeni hocan {1}. Sıfırdan bir güven kurmanız gerekecek. Motivasyon -1.": "Du und {0} habt euch getrennt. Dein neuer Trainer ist {1}. Ihr müsst das Vertrauen von Grund auf aufbauen. Motivation -1.",
  "🫂 Bir Baba Gibi": "🫂 Wie ein Vater",
  "Gece salonda yalnız kaldınız. {0} eski bir fotoğraf çıkardı: ilk antrenmanın, eldivenler elinden büyük. “O gün kapıdan girdiğinde ne olacağını biliyordum,” dedi.": "Spät in der Nacht, allein im Gym, holte {0} ein altes Foto hervor: deine erste Einheit, die Handschuhe größer als deine Hände. „An dem Tag, als du durch diese Tür kamst, wusste ich es“, sagte er.",
  "Sarıl": "Ihn umarmen",
  "“Her şeyi sana borçluyum.”": "„Ich verdanke dir alles.“",
  "{0} ile ilk antrenman fotoğrafı": "Foto der ersten Einheit mit {0}",
  "Eldivenler elinden büyük. Arkasında hocanın el yazısı: “Bir gün.”": "Handschuhe größer als deine Hände. Auf der Rückseite, in der Schrift deines Trainers: „Eines Tages.“",
  "Uzun süre konuşmadınız. Gerek yoktu. Motivasyon +2.": "Lange hat keiner von euch etwas gesagt. Es war nicht nötig. Motivation +2.",
  "“Hayır,” dedi, “her şeyi kendine borçlusun. Ben sadece kapıyı açtım.” Motivasyon +2.": "„Nein“, sagte er, „du verdankst alles dir selbst. Ich habe nur die Tür geöffnet.“ Motivation +2.",
  "📨 Rakip Kampın Teklifi": "📨 Angebot eines rivalisierenden Camps",
  "Büyük bir salon {0} hocana baş antrenörlük teklif etmiş, maaşı iki katı. Sana söylemedi; sen başkasından duydun.": "Ein großes Gym hat deinem Trainer {0} einen Cheftrainer-Job zum doppelten Gehalt angeboten. Er hat es dir nicht gesagt; du hast es von jemand anderem gehört.",
  "Ona zam yap ve kalmasını iste ({0})": "Ihm mehr Gehalt geben und ihn bitten zu bleiben ({0})",
  "Onu tebrik et, gitmesine izin ver": "Gratulieren und ihn gehen lassen",
  "Sessiz kal, kararı ona bırak": "Schweigen, es ihm überlassen",
  "{0} teklifi reddetti: “Benim dövüşçüm burada.” Bağ çok güçlendi.": "{0} hat abgelehnt: „Mein Kämpfer ist hier.“ Die Bindung ist viel stärker.",
  "{0} gözleri dolu gitti, giderken seni yeni hocan {1} ile tanıştırdı. Motivasyon +1.": "{0} ging mit Tränen in den Augen und stellte dir beim Abschied deinen neuen Trainer {1} vor. Motivation +1.",
  "{0} kaldı. “Sana sormadan karar vermem gerekirdi, ama burası benim evim,” dedi.": "{0} ist geblieben. „Ich hätte entscheiden sollen, ohne dich zu fragen, aber das hier ist mein Zuhause“, sagte er.",
  "{0} teklifi kabul etti. Yeni hocan {1}.": "{0} hat das Angebot angenommen. Dein neuer Trainer ist {1}.",
  "🏥 Hocanın Sağlığı": "🏥 Die Gesundheit deines Trainers",
  "{0} birkaç haftadır öksürüyordu. Doktorlar dinlenmesini söyledi ama o kampı bırakmak istemiyor.": "{0} hustet seit Wochen. Die Ärzte haben ihm Ruhe verordnet, aber er weigert sich, das Camp zu verlassen.",
  "Zorla tatile gönder, kampı asistan yönetsin": "Ihn zur Ruhe zwingen; der Assistent leitet das Camp",
  "Onun kararına saygı duy": "Seine Entscheidung respektieren",
  "Önce kızdı, sonra teşekkür etti. Bir ay sonra eskisinden dinç döndü. Bağ güçlendi.": "Erst war er wütend, dann dankbar. Einen Monat später kam er stärker denn je zurück. Die Bindung ist gewachsen.",
  "Kampı yönetti ama her gece onu merak ettin. Motivasyon -1.": "Er hat das Camp geleitet, aber du hast dir jede Nacht Sorgen gemacht. Motivation -1.",
  "🕊️ Hocanın Vedası": "🕊️ Der Abschied deines Trainers",
  "{0} seni salonun ortasına çağırdı: “Yaşlandım evlat. Sana öğretebileceğim her şeyi öğrettim.” Yerine kendi asistanını önerdi.": "{0} rief dich in die Mitte des Gyms: „Ich werde alt, Kleiner. Ich habe dir alles beigebracht, was ich kann.“ Er schlug vor, dass sein Assistent übernimmt.",
  "Son bir antrenman yapın": "Eine letzte Einheit machen",
  "Veda yemeği düzenle": "Ein Abschiedsessen geben",
  "{0} ile son fotoğraf": "Letztes Foto mit {0}",
  "Son antrenmanın sonunda minderde yan yana": "Nach der letzten Einheit Seite an Seite auf der Matte",
  "Veda yemeğinde, bütün salon bir arada": "Beim Abschiedsessen, das ganze Gym zusammen",
