  "{0} emekli oldu ama her maçını tribünden izleyeceğine söz verdi. Yeni hocan {1}. Motivasyon +1.": "{0} hat aufgehört, aber versprochen, jeden Kampf von der Tribüne aus zu verfolgen. Dein neuer Trainer ist {1}. Motivation +1.",
