  "🎬 Film Teklifi": "🎬 Filmangebot",
  "Bir yapımcı seni “{0}” adlı aksiyon filminde kötü adam olarak istiyor. Çekimler üç hafta, Hollywood'dan bir yönetmen.": "Ein Produzent will dich als Bösewicht im Actionfilm „{0}“. Drei Wochen Dreh, ein Hollywood-Regisseur.",
  "Sette herkes senden korktu, sonra sevdi. Fragman bir günde 20 milyon izlendi.": "Am Set hatten erst alle Angst vor dir, dann liebten sie dich. Der Trailer hatte an einem Tag 20 Millionen Aufrufe.",
  "🎥 Belgesel Teklifi": "🎥 Doku-Angebot",
  "Bir yayın platformu senin hayatını anlatan bir belgesel çekmek istiyor. Kamera ekibi bir sonraki kampın boyunca peşinde olacak; memleketine, ailene de gidecekler.": "Eine Streamingplattform will eine Doku über dein Leben drehen. Ein Kamerateam begleitet dich durch dein nächstes Camp und besucht deine Heimatstadt und Familie.",
  "Kafesten Kemere": "Vom Käfig zum Gürtel",
  "Kamera her şeyi çekti: sabah koşularını, kesimin zor anlarını, annenin mutfağını. İzleyiciler seni tanıdı.": "Die Kamera hat alles eingefangen: Morgenläufe, die harten Momente beim Gewichtmachen, die Küche deiner Mutter. Die Zuschauer haben dich kennengelernt.",
  "📺 Reklam Yüzü": "📺 Gesicht einer Kampagne",
  "{0} yeni kampanyasının yüzü olmanı istiyor. Bir günlük çekim, ülke çapında billboard.": "{0} will dich als Gesicht seiner neuen Kampagne. Ein Drehtag, Plakate im ganzen Land.",
  "Şehrin her köşesinde yüzün var. Annen her billboard'un fotoğrafını çekiyor.": "Dein Gesicht ist an jeder Ecke der Stadt. Deine Mutter fotografiert jedes Plakat.",
  "🎙️ Talk Show Daveti": "🎙️ Einladung in eine Talkshow",
  "“{0}” programı seni konuk olarak çağırdı. Sunucu ünlü, şaka kaldırırsa salon seninle.": "„{0}“ hat dich als Gast eingeladen. Der Moderator ist berühmt; wenn du Spaß verstehst, gehört dir das Publikum.",
  "Sunucuya canlı yayında armbar gösterdin. Klip her yerde.": "Du hast dem Moderator live im Fernsehen einen Armbar gezeigt. Der Clip ist überall.",
  "📰 Dergi Kapağı": "📰 Magazin-Cover",
  "{0} dergisi seni kapağa koymak istiyor. Bir günlük çekim, büyük bir röportaj.": "Das Magazin {0} will dich aufs Cover. Ein Drehtag und ein großes Interview.",
  "Kapak büfelerde tükendi. Bir kopyası salonun duvarında.": "Die Ausgabe war an den Kiosken ausverkauft. Ein Exemplar hängt an der Gym-Wand.",
  "📺 Dizi Konuk Rolü": "📺 Gastrolle im Fernsehen",
  "Sevilen dizi “{0}” bir bölümde seni kendini oynaman için istiyor. İki hafta çekim.": "Die Erfolgsserie „{0}“ will, dass du in einer Folge dich selbst spielst. Zwei Wochen Dreh.",
  "Sahnen sosyal medyada dolaştı. Senaristler “bir sezon daha gel” diyor.": "Deine Szene ging in den sozialen Medien herum. Die Autoren wollen dich nächste Staffel zurück.",
  "Film": "Film",
