  "Sonraki kampta gelişim %{0} azalır.": "Der Fortschritt deines nächsten Camps sinkt um {0} %.",
  "Kampına etkisi yok.": "Kein Einfluss auf dein Camp.",
  "Ücret: ${0}": "Gage: {0} $",
  "Reddet, odak kafeste": "Ablehnen, auf den Käfig konzentrieren",
  "“Şu an tek işim dövüşmek.” Hocan bu cevabı çok sevdi. Motivasyon +1.": "„Im Moment ist Kämpfen mein einziger Job.“ Dein Trainer liebte diese Antwort. Motivation +1.",
  "🎬 {0}: {1} projesinde yer aldı.": "🎬 {0} hat bei einem {1}-Projekt mitgemacht.",
  "{0} +${1}, popülerlik +{2}, {3} takipçi.": "{0} +{1} $, Popularität +{2}, {3} Follower.",
  "Serbest": "Frei",
  "Ne canın isterse. Kilo vermek zorlaşır, iyileşme biraz yavaşlar.": "Was du willst. Gewicht machen wird schwerer und die Erholung etwas langsamer.",
  "Ev yemekleri, ölçülü porsiyon. Etkisi yok.": "Hausmannskost, vernünftige Portionen. Kein Effekt.",
  "Hazır diyet menüsü: maç başı ${0}. Kilo vermek kolaylaşır, iyileşme hızlanır.": "Meal-Prep-Ernährungsplan: {0} $ pro Kampf. Gewicht machen wird leichter und die Erholung schneller.",
  "Değişken": "Unregelmäßig",
  "Geç saatlere kadar sosyal hayat: maç başı popülerlik +1, iyileşme normal.": "Gesellschaftsleben bis spät: Popularität +1 pro Kampf, normale Erholung.",
  "Düzenli": "Regelmäßig",
  "Her gece 8 saat, telefon yatak odasına girmiyor: iyileşme hızlanır.": "Jede Nacht acht Stunden, kein Handy im Schlafzimmer: schnellere Erholung.",
