  "Zirve yılları": "Beste Jahre",
  "Hız, güç ve kondisyon en iyi hâlinde. Kemer için en doğru zaman.": "Tempo, Kraft und Kondition auf dem Höhepunkt. Die richtige Zeit, um einen Gürtel zu jagen.",
  "Gelişim yavaşlıyor ama kafes zekân her maçla artıyor.": "Der Fortschritt wird langsamer, aber dein Kampf-IQ wächst mit jedem Kampf.",
  "Gün batımı": "Spätphase",
  "Her yıl hız ve çene biraz düşer, IQ artar. Akıllı dövüşmek zorundasın.": "Jedes Jahr sinken Tempo und Kinn etwas und der IQ steigt. Du musst klug kämpfen.",
  "Yaşın, izlerin ve günlük rutinin. Küçük seçimler, uzun bir kariyerde büyük fark yaratır.": "Dein Alter, deine Narben und dein Alltag. Kleine Entscheidungen machen über eine lange Karriere einen großen Unterschied.",
