  "Her iz kampta sakatlık riskini biraz artırır. Fizyoterapist bu riski azaltır.": "Jede Narbe erhöht das Verletzungsrisiko im Camp leicht. Ein Physiotherapeut senkt dieses Risiko.",
  "Vücudunda kalıcı iz yok. Ağır sakatlıklar iyileşirken bazen iz bırakır.": "Keine bleibenden Narben. Schwere Verletzungen hinterlassen beim Heilen manchmal Spuren.",
