  "Kendi dövüş organizasyonunu kur: dövüşçü imzala, gece düzenle, bilet sat, yayın anlaşması yap. Bu sefer afişi sen yazıyorsun.": "Gründe deine eigene Kampforganisation: Verpflichte Kämpfer, veranstalte Events, verkaufe Tickets, hol dir TV-Deals. Diesmal schreibst du das Poster.",
