  "Gece düzenlemek için kontratı süren en az 4 dövüşçü gerekiyor. Keşif sekmesinden imzala.": "Du brauchst mindestens 4 Kämpfer unter Vertrag, um ein Event zu veranstalten. Verpflichte welche im Tab Scouting.",
