  "İmza parası, maç başı ücretin iki katıdır. Kontrat 4 maç sürer. Her geceden sonra yeni adaylar gelir.": "Das Handgeld ist doppelt so hoch wie die Gage pro Kampf. Verträge laufen über 4 Kämpfe. Nach jedem Event kommen neue Talente.",
