  "Bir kemer kazan ya da popülerlik 55.": "Gewinne einen Gürtel oder erreiche Popularität 55.",
  "🏠 {0} belediyesi doğduğun sokağa adını verdi!": "🏠 {0} hat die Straße, in der du geboren wurdest, nach dir benannt!",
  "Stadyumda pankart": "Stadionbanner",
  "Memleketinde bir maç kazan ya da popülerlik 70.": "Gewinne einen Kampf in deiner Heimatstadt oder erreiche Popularität 70.",
  "🏠 {0} takımının maçında dev bir pankart açıldı: senin yüzün.": "🏠 Beim Spiel des Teams aus {0} wurde ein riesiges Banner entrollt: dein Gesicht.",
  "Meydanda heykelin": "Deine Statue auf dem Platz",
  "UCC şampiyonu ol ya da Hall of Fame'e gir.": "Werde UCC-Champion oder komm in die Hall of Fame.",
  "🏠 {0} meydanına bronz heykelin dikildi. Kemerli, kollar havada.": "🏠 Auf dem Hauptplatz von {0} wurde eine Bronzestatue von dir aufgestellt. Gürtel um, Arme hoch.",
  "Eski salonun yeni minderleri, yeni torbaları ve senin adını taşıyan tabelasıyla açıldı. Çocuklar sıraya girdi. Popülerlik +3, motivasyon +1 (${0}).": "Dein altes Gym hat mit neuen Matten, neuen Säcken und einem Schild mit deinem Namen wiedereröffnet. Die Kinder standen Schlange. Popularität +3, Motivation +1 ({0} $).",
  "Meydanda yürüyemedin bile; herkes fotoğraf istedi. Annenin yemeği her şeye değdi. Motivasyon +1, sağlık +5, popülerlik +1.": "Du kamst nicht mal über den Platz; alle wollten ein Foto. Das Essen deiner Mutter war alles wert. Motivation +1, Gesundheit +5, Popularität +1.",
  "Salonda çocuklara bir antrenman verdin, akşam ailenle sofraya oturdun. Motivasyon +1, sağlık +5.": "Du hast im Gym eine Einheit für die Kinder geleitet und mit deiner Familie gegessen. Motivation +1, Gesundheit +5.",
  "Eski sokaklarda dolaştın, annenin çorbası her şeyi iyileştirdi. Motivasyon +1, sağlık +5.": "Du bist durch die alten Straßen gelaufen und die Suppe deiner Mutter hat alles wieder gerichtet. Motivation +1, Gesundheit +5.",
  "KAHVE": "CAFÉ",
  "{0} SK.": "{0}-STR.",
  "Ünlendikçe memleketin değişir. Her aşama kasabada iz bırakır.": "Je berühmter du wirst, desto mehr verändert sich deine Heimatstadt. Jeder Meilenstein hinterlässt Spuren im Ort.",
