  "KAMP SEANSI · İSTEĞE BAĞLI": "CAMP-EINHEIT · OPTIONAL",
  "{0}: 15 saniyelik bir mini oyun. İyi oynarsan bütün kamp daha verimli geçer, sakatlık riski düşer.": "{0}: ein 15-Sekunden-Minispiel. Spielst du gut, ist das ganze Camp produktiver und das Verletzungsrisiko geringer.",
