  "SON OLAYLAR": "NEUESTES",
  "{0}. HF": "WO. {0}",
  "Kamp hazır. Haftalar kendiliğinden akacak; bir karar gerektiğinde duracak.": "Das Camp ist bereit. Die Wochen laufen von selbst und halten an, wenn eine Entscheidung nötig ist.",
  "Sparda sert bir darbe aldın; kaburgaların sızlıyor. {0} kararı sana bırakıyor.": "Du hast im Sparring einen harten Treffer kassiert; deine Rippen schmerzen. {0} überlässt dir die Entscheidung.",
  "Birkaç gün dinlen": "Ein paar Tage ausruhen",
  "Dişini sık, devam et": "Zähne zusammenbeißen, weitermachen",
  "{0} kampın gidişatından memnun ve gece seansları eklemek istiyor.": "{0} ist zufrieden mit dem Camp und will Nachteinheiten hinzufügen.",
  "Ekstra seansı ekle": "Die Extraeinheiten hinzufügen",
  "Dinlenmeyi tercih et": "Stattdessen Ruhe wählen",
  "Diyetisyen tartıyı erken düşünmeni öneriyor: şimdiden kalori kesersen son 48 saat kolaylaşır.": "Dein Ernährungsberater rät, früh ans Wiegen zu denken: Reduzierst du jetzt die Kalorien, werden die letzten 48 Stunden leichter.",
  "Diyete şimdi başla": "Jetzt mit der Diät beginnen",
  "Önce kampa odaklan": "Erst aufs Camp konzentrieren",
  "Büyük bir spor kanalı kamptan röportaj istiyor. Bir gün sürer.": "Ein großer Sportsender will ein Interview aus dem Camp. Es würde einen Tag kosten.",
  "Röportajı ver": "Das Interview geben",
  "Kampı koru": "Das Camp schützen",
  "Ünlü bir antrenör bir haftalığına kampına katılabilir. Ücreti ${0}.": "Ein berühmter Trainer könnte eine Woche zu deinem Camp kommen. Sein Honorar: {0} $.",
  "Davet et (${0})": "Ihn einladen ({0} $)",
  "Gerek yok": "Nicht nötig",
  "İki gün buz ve masaj. Biraz yavaşladın ama vücudun teşekkür ediyor.": "Zwei Tage Eis und Massage. Du hast etwas Tempo rausgenommen, aber dein Körper dankt es dir.",
  "Devam ettin. Hocan seni izliyor; bir şey olursa erken fark edecek.": "Du hast weitergemacht. Dein Trainer schaut genau hin und wird jedes Problem früh erkennen.",
  "Gece seansları zorladı ama verimli geçti (sağlık -6).": "Die Nachteinheiten waren hart, aber produktiv (Gesundheit -6).",
  "Dinlenmeyi seçtin; enerjin yerinde (sağlık +4).": "Du hast dich für Ruhe entschieden; deine Energie ist gut (Gesundheit +4).",
  "Tabağın küçüldü, keyfin biraz kaçtı (motivasyon -1) ama tartı haftası daha rahat geçecek.": "Kleinere Teller, etwas weniger Spaß (Motivation -1), aber die Woche des Wiegens wird leichter.",
  "Kilo işini son haftaya bıraktın.": "Du hast das Gewicht für die letzte Woche aufgehoben.",
  "Röportaj çok izlendi (popülerlik +2); bir antrenman günü kaçtı.": "Das Interview hatte viele Aufrufe (Popularität +2); du hast einen Trainingstag verloren.",
  "Kapıyı kapattın, odak tamamen kampta.": "Du hast die Tür zugemacht; volle Konzentration aufs Camp.",
  "Misafir antrenör bir haftada kafanda yeni kapılar açtı. Kamp daha verimli.": "In einer Woche hat der Gasttrainer dir neue Türen im Kopf geöffnet. Das Camp ist produktiver.",
  "Kendi ekibinle devam ettin.": "Du hast mit deinem eigenen Team weitergemacht.",
