  "Dart": "Darts",
  "Üç atış. Nişangâh kayarken tam ortaya geldiğinde dokun. Hızın ne kadar yüksekse nişangâh o kadar yavaş kayar.": "Drei Würfe. Tippe, wenn das Fadenkreuz übers Bullseye wandert. Je höher dein Tempo, desto langsamer wandert es.",
  "Yumruk makinesi": "Boxautomat",
  "Güç çubuğu dolup boşalırken zirvede vur. Vuruş gücün skoru büyütür.": "Schlag zu, wenn der Kraftbalken am höchsten ist. Dein Striking-Wert erhöht die Punktzahl.",
