  "Rakip mesajı paylaştı: “Saygı gösterdim, karşılığı bu.” Gündem yükseldi ama bazı hayranlar soğudu. Takipçi {0}.": "Dein Gegner hat sie gepostet: „Ich habe Respekt gezeigt, und das ist die Antwort.“ Das Interesse stieg, aber manche Fans wurden kühler. Follower {0}.",
  "Promotör ofisi": "Büro des Promoters",
  "Maçı satmamız lazım. Önümüzdeki hafta 3 şehirde basın turu ayarlayabiliriz. Yorucu ama bilet satışını uçurur. Var mısın?": "Wir müssen diesen Kampf verkaufen. Nächste Woche können wir eine Pressetour durch 3 Städte machen. Anstrengend, aber die Tickets werden weggehen. Bist du dabei?",
  "Varım, tura çıkalım": "Bin dabei, auf Tour",
  "Kampı bölmem": "Ich unterbreche das Camp nicht",
  "Basın turu": "Pressetour",
  "Tur olay oldu, biletler kapışılıyor. Ama yol yorgunluğu kampı biraz bozdu: motivasyon -1. Takipçi {0}.": "Die Tour war ein Erfolg, die Tickets gehen weg. Aber die Reise hat dich zermürbt: Motivation -1. Follower {0}.",
  "Promotör homurdandı ama kampına dokunmadın: motivasyon +1.": "Der Promoter hat gemurrt, aber du hast dein Camp geschützt: Motivation +1.",
  "Kamp başlamadan bu akşam baş başa bir yemek? Sonra haftalarca yüzünü göremeyeceğim. ❤️": "Heute Abend Essen zu zweit, bevor das Camp beginnt? Danach sehe ich dich wochenlang nicht. ❤️",
  "Tabii, rezervasyon benden": "Klar, ich reserviere einen Tisch",
  "Maçtan sonra telafi ederim": "Ich mach's nach dem Kampf wieder gut",
  "Güzel bir akşamdı. Kafan rahat kampa girdin: motivasyon +1 (−{0}).": "Ein schöner Abend. Du gehst mit klarem Kopf ins Camp: Motivation +1 (−{0}).",
  "“Söz mü?” dedi. Söz verdin. Maçtan sonra unutma.": "„Versprochen?“ Du hast es versprochen. Vergiss es nach dem Kampf nicht.",
  "Annem": "Mama",
  "Oğlum yine maçın varmış, komşudan duydum. Yemeğini düzgün ye, kilo vereceğim diye kendini aç bırakma. Dua ediyorum.": "Hab von der Nachbarin gehört, dass du wieder einen Kampf hast. Iss ordentlich, hungere dich beim Gewichtmachen nicht aus. Ich bete für dich.",
  "Baban maçı büyük ekranda izleyecekmiş, bütün mahalleyi çağırdı. Dikkat et kendine yavrum.": "Dein Vater schaut auf der großen Leinwand, er hat das ganze Viertel eingeladen. Pass auf dich auf, Schatz.",
  "Hemen ara 📞": "Sofort anrufen 📞",
  "“Merak etme anne” yaz": "„Keine Sorge, Mama“ schreiben",
  "Yarım saat konuştunuz. Sesini duymak iyi geldi: motivasyon +1.": "Ihr habt eine halbe Stunde telefoniert. Ihre Stimme zu hören hat geholfen: Motivation +1.",
  "“Tamam yavrum, Allah utandırmasın” yazdı. ❤️": "Sie schrieb: „Okay, Schatz, Gott sei mit dir.“ ❤️",
  "Rakibinin stilini taklit edebilirim. Bu akşam salon kapanınca ekstra spar yapalım mı? 🥊": "Ich kann den Stil deines Gegners nachmachen. Heute Abend, wenn das Gym zu ist, extra Sparring? 🥊",
  "Yapalım": "Machen wir",
  "Bu akşam dinlenmem lazım": "Ich brauche heute Abend Ruhe",
  "Sert ama faydalı bir spar. Bağınız güçlendi, biraz yıprandın (sağlık −3).": "Hartes, aber nützliches Sparring. Eure Bindung ist gewachsen, du hast etwas eingesteckt (Gesundheit −3).",
  "“Peki kanka” yazdı. Biraz bozulmuş gibi.": "Er schrieb „Okay, Bruder.“ Scheint etwas gekränkt.",
  "Şanslıydın. Bunu ikimiz de biliyoruz. Rövanşta gerçeği göreceksin.": "Du hattest Glück. Das wissen wir beide. Im Rückkampf siehst du die Wahrheit.",
  "Bu gece daha iyiydin, tebrik ederim. Bir gün rövanş isterim ama önce kendimi toparlayacağım. 🤝": "Du warst heute Abend besser, Glückwunsch. Ich hätte gern irgendwann einen Rückkampf, aber erst sammle ich mich. 🤝",
  "Saygılar, iyi dövüştün": "Respekt, guter Kampf",
  "Sıraya gir 😎": "Stell dich hinten an 😎",
  "Ne zaman istersen": "Jederzeit",
  "Mesajı paylaştı: “Gerçek bir şampiyon adayı.” Popülerlik +1.": "Er hat es geteilt: „Ein echter Titelanwärter.“ Popularität +1.",
  "Ekran görüntüsü taraftar sayfalarında dolaşıyor. Takipçi {0}.": "Der Screenshot ist auf allen Fanseiten. Follower {0}.",
  "Rekabet kızışıyor. Bir gün yine karşılaşırsanız ortalık yanar.": "Die Rivalität heizt sich auf. Trefft ihr euch eines Tages wieder, wird es Feuer geben.",
  "Hocam": "Trainer",
  "Kafana takma. Yarın sabah salona erken gel, maçı birlikte izleyelim. Neyi yanlış yaptığımızı ben de görmek istiyorum.": "Grübel nicht drüber. Komm morgen früh ins Gym, wir schauen uns den Kampf zusammen an. Ich will auch sehen, was wir falsch gemacht haben.",
  "Sabah oradayım": "Ich bin morgen früh da",
  "Birkaç gün kafa dinleyeceğim": "Ich brauche ein paar Tage frei",
  "Maçı kare kare izlediniz. Hocanla bağın güçlendi.": "Ihr habt den Kampf Bild für Bild durchgesehen. Deine Bindung zum Trainer ist gewachsen.",
  "Biraz uzaklaştın, iyi geldi: motivasyon +1. Hocan biraz kırıldı.": "Etwas Abstand hat gutgetan: Motivation +1. Dein Trainer ist etwas gekränkt.",
  "Gurur duydum. Ama şımarmak yok, pazartesi idmandayız. 😄": "Stolz auf dich. Aber werd nicht übermütig, Montag ist Training. 😄",
  "Her şey senin sayende hocam": "Das verdanke ich alles dir, Coach",
  "Pazartesi ilk ben gelirim": "Am Montag bin ich als Erster da",
  "Hocan duygulandı. Bağınız güçlendi.": "Dein Trainer wurde emotional. Eure Bindung ist gewachsen.",
  "“Göreceğiz” dedi. Motivasyon +1.": "„Wir werden sehen“, sagte er. Motivation +1.",
  "Efsane şampiyon": "Legendärer Champion",
  "Eski UCC şampiyonu": "Ehemaliger UCC-Champion",
  "Onur listesindeki usta": "Hall-of-Fame-Meister",
  "Kemeri almak zor, tutmak daha zor. Hoş geldin şampiyon. Bir gün kahve içelim, anlatacak çok şeyim var.": "Den Gürtel zu gewinnen ist schwer, ihn zu behalten noch schwerer. Willkommen, Champ. Lass uns mal einen Kaffee trinken, ich hab dir viel zu erzählen.",
  "Benim için onur": "Es ist mir eine Ehre",
  "Teşekkürler usta": "Danke, Meister",
  "Mesajı paylaştın, herkes konuşuyor: popülerlik +2, motivasyon +1.": "Du hast die Nachricht geteilt, alle reden darüber: Popularität +2, Motivation +1.",
  "Emir (12)": "Jake (12)",
  "Zeynep (11)": "Emma (11)",
  "Kerem (13)": "Liam (13)",
  "Ayşe (10)": "Mia (10)",
  "Senin maçını izledikten sonra salona yazıldım! Annem bir sesli mesaj atarsan çok mutlu olacağımı söyledi. Lütfen 🥺": "Nachdem ich deinen Kampf gesehen habe, bin ich in ein Gym gegangen! Meine Mama sagt, eine Sprachnachricht von dir würde mich so glücklich machen. Bitte 🥺",
  "Sesli mesaj gönder 🎙️": "Sprachnachricht schicken 🎙️",
  "İmzalı eldiven yolla 🥊": "Signierte Handschuhe schicken 🥊",
  "Annesi videoyu paylaştı, çocuk sevinçten ağlıyor. Motivasyon +1. Takipçi {0}.": "Die Mutter hat das Video gepostet, das Kind weint vor Freude. Motivation +1. Follower {0}.",
  "Eldiveni odasının duvarına asmış. Haber oldu: popülerlik +1 (−{0}).": "Die Handschuhe hängen an der Wand des Kindes. Es kam in den Nachrichten: Popularität +1 (−{0}).",
