  "Merhaba! Ürünümüzü hikâyende paylaşırsan {0} ödemek istiyoruz. Tek paylaşım, 24 saat.": "Hallo! Wir würden dir {0} zahlen, wenn du unser Produkt in deiner Story zeigst. Ein Post, 24 Stunden.",
