  "Pazarlık et": "Verhandeln",
  "Paylaştın, ödeme geldi: +{0}.": "Du hast es gepostet, Zahlung erhalten: +{0}.",
  "Pazarlık tuttu! +{0}.": "Die Verhandlung hat geklappt! +{0}.",
  "“Bütçemiz bu kadar” deyip başka bir dövüşçüyle anlaştılar.": "„Das ist unser Budget“, sagten sie, und nahmen einen anderen Kämpfer.",
  "Kibarca reddettin.": "Du hast höflich abgelehnt.",
  "Kafes Postası": "Cage Post",
  "Dövüş Dergisi": "Fight Magazine",
  "Hayat hikâyeni anlatacağın özel bir röportaj yapmak istiyoruz. Çocukluğun, ilk salonun, hayallerin… Ne dersin?": "Wir hätten gern ein Exklusivinterview über deine Lebensgeschichte. Deine Kindheit, dein erstes Gym, deine Träume… Was sagst du?",
  "Kabul, her şeyi anlatırım": "Ja, ich erzähle alles",
  "Sadece spordan konuşurum": "Nur über den Sport",
  "Röportaj çok okundu, insanlar seni daha yakından tanıdı: popülerlik +2.": "Das Interview wurde viel gelesen, die Leute haben dich besser kennengelernt: Popularität +2.",
  "Kısa ve profesyonel bir röportaj oldu: popülerlik +1.": "Ein kurzes, professionelles Interview: Popularität +1.",
  "“Kapımız her zaman açık” dediler.": "„Unsere Tür steht immer offen“, sagten sie.",
  "Sen dövüşçü değilsin, Instagram fenomenisin. 🤡": "Du bist kein Kämpfer, du bist ein Influencer. 🤡",
  "Bir sonraki maçında uyutulacaksın, hatırla bu mesajı.": "Im nächsten Kampf gehst du k.o., denk an diese Nachricht.",
  "Hocan bile sana inanmıyor, belli.": "Nicht mal dein Trainer glaubt an dich, das sieht man.",
  "Engelle": "Blockieren",
  "Esprili cevap ver 😂": "Mit einem Witz antworten 😂",
  "Engelledin. Sessizlik huzurdur.": "Blockiert. Stille ist Frieden.",
  "Cevabın viral oldu, herkes troll'e gülüyor. Takipçi {0}.": "Deine Antwort ging viral, alle lachen über den Troll. Follower {0}.",
  "Troll ekran görüntüsünü çarpıtarak paylaştı. Bir süre tartışıldı: popülerlik −1.": "Der Troll hat einen verfälschten Screenshot gepostet. Eine Weile wurde darüber diskutiert: Popularität −1.",
