  "Satın alma şu an yapılamadı. Biraz sonra tekrar dene.": "Der Kauf konnte gerade nicht abgeschlossen werden. Versuch es gleich noch einmal.",
  "EFSANELER PAKETİ": "LEGENDEN-PAKET",
  "{0} efsane, {1} bölüm, her efsaneye özel şort. Tek seferlik alım; sonra gelecek efsaneler de dahil.": "{0} Legenden, {1} Kapitel, exklusive Shorts für jede Legende. Einmaliger Kauf; zukünftige Legenden inklusive.",
