  "{0} bölüm": "{0} Kapitel",
  "Ya da bir efsaneyi yaşa": "Oder erlebe die Geschichte einer Legende",
  "{0}: Dublin'den çifte şampiyonluğa, rehberli 9 bölüm. Ücretsiz.": "{0}: von Dublin zum Champion in zwei Gewichtsklassen, 9 geführte Kapitel. Kostenlos.",
  "1. bölümü ücretsiz oyna": "Kapitel 1 kostenlos spielen",
