  "HİKÂYE BURADA BİTMİYOR": "DIE GESCHICHTE ENDET HIER NICHT",
  "Sıradaki bölüm: {0} ({1}). Önünde {2} bölüm daha var.": "Nächstes Kapitel: {0} ({1}). Noch {2} Kapitel warten.",
  "{0} hikâyesine kaldığın yerden devam et:": "Setz die Geschichte von {0} dort fort, wo du aufgehört hast:",
  "Paket almadan da bu kariyere normal devam edebilirsin; yalnızca bölüm hedefleri ilerlemez.": "Du kannst diese Karriere ohne das Paket weiterspielen; nur die Kapitelziele kommen nicht voran.",
  "SIRADAKİ EFSANE": "NÄCHSTE LEGENDE",
  "ŞAMPİYONSUN. SIRADA EFSANELER VAR": "DU BIST CHAMPION. ALS NÄCHSTES DIE LEGENDEN",
  "{0} kemeri aldıktan sonra kadın MMA'sını dünyaya tanıttı. Onun yolunu bölüm bölüm yaşa.": "Nach dem Gürtelgewinn brachte {0} das Frauen-MMA in die Welt. Erlebe ihren Weg Kapitel für Kapitel.",
  "{0} bu kemeri 29-0'lık yenilmez bir rekorla taşıdı. Onun yolunu bölüm bölüm yaşa.": "{0} trug diesen Gürtel mit einer ungeschlagenen Bilanz von 29-0. Erlebe seinen Weg Kapitel für Kapitel.",
  "İstersen önce menüdeki Efsane Yolları'ndan her efsanenin 1. bölümünü ücretsiz dene.": "Kapitel 1 jeder Legende kannst du unter Legenden-Wege im Menü kostenlos ausprobieren.",
  "{0} nasıl efsane oldu?": "Wie wurde {0} zur Legende?",
  "Hikâyesini bölüm bölüm oyna.": "Spiel die Geschichte Kapitel für Kapitel.",
