  "Efsaneler Paketi dahil: bütün Efsane Yolları hikâyeleri": "Legenden-Paket inklusive: jede Geschichte der Legenden-Wege",
  "🔒 {0} hikâyesinin devamı Efsaneler Paketi'nde. Kariyerine normal devam edebilirsin.": "🔒 Der Rest der Geschichte von {0} ist im Legenden-Paket. Du kannst deine Karriere wie gewohnt weiterspielen.",
  "📖 EFSANE YOLU DEVAM EDİYOR: Bölüm {0}.": "📖 DER LEGENDEN-WEG GEHT WEITER: Kapitel {0}.",
