  "Altın Seri ve Şampiyon çerçevesi": "Gold-Serie und Champion-Rahmen",
  "Şampiyon ol · {0}": "Werde Champion · {0}",
  "BUGÜN 3 REKLAM İZLEDİN": "DU HAST HEUTE 3 WERBUNGEN GESCHAUT",
  "Şampiyon Paketi ile bütün ödüller reklamsız ve anında gelir. Tek seferlik alım, abonelik yok.": "Mit dem Champion-Paket kommt jede Belohnung sofort, ohne Werbung. Einmaliger Kauf, kein Abo.",
  "BÜTÜN YUVALAR DOLU": "ALLE SLOTS SIND BELEGT",
  "Şampiyon Paketi ile 5 kariyer yuvası: yeni bir hikâyeye başlamak için eskisini silmen gerekmez.": "Das Champion-Paket gibt dir 5 Karriere-Slots: Du musst keine alte Geschichte löschen, um eine neue zu beginnen.",
  "BİR ŞAMPİYONA YAKIŞIR PAKET": "EIN PAKET FÜR EINEN CHAMPION",
  "Kemeri kazandın. Şampiyon Paketi ile oyunun bütün ekstralarını aç.": "Du hast den Gürtel gewonnen. Schalte mit dem Champion-Paket alle Extras des Spiels frei.",
  "👑 Şampiyon Paketi ile reklamsız, anında": "👑 Ohne Werbung und sofort mit dem Champion-Paket",
  "👑 ŞAMPİYON PAKETİ": "👑 CHAMPION-PAKET",
  "İstediğin iki dövüşçü, istediğin sıklet, istediğin kadar maç. Kendi efsanelerini de efsanelere karşı dövüştür.": "Zwei beliebige Kämpfer, jede Gewichtsklasse, so viele Kämpfe, wie du willst. Schick auch deine eigenen Legenden gegen die Legenden.",
  "Hayalî Maç Stüdyosu": "Traumkampf-Studio",
  "Rövanş": "Rückkampf",
  "Yeni eşleşme": "Neue Paarung",
  "Hayalî Maçlar'a dön": "Zurück zu den Traumkämpfen",
  "HAYALÎ MAÇ STÜDYOSU": "TRAUMKAMPF-STUDIO",
  "Kimi yöneteceksin?": "Wen steuerst du?",
  "Rakibini seç.": "Wähle deinen Gegner.",
  "Kırmızı köşe": "Rote Ecke",
  "Mavi köşe": "Blaue Ecke",
  "Emekli olan dövüşçülerini emeklilik ekranından Efsanelerim'e ekleyebilirsin; burada efsanelere karşı dövüşürler.": "Deine zurückgetretenen Kämpfer kannst du über den Ruhestandsbildschirm zu Meine Legenden hinzufügen; hier kämpfen sie gegen die Legenden.",
  "⭐ Efsanem": "⭐ Meine Legende",
  "Rakibi değiştir": "Gegner wechseln",
  "Zirvedeki halleriyle · 5 raunt": "Auf dem Höhepunkt · 5 Runden",
  "{0} vs {1}": "{0} gegen {1}",
  "İstediğin iki dövüşçü, istediğin sıklet, sınırsız maç. Kendi efsanelerin de burada.": "Zwei beliebige Kämpfer, jede Gewichtsklasse, unbegrenzt Kämpfe. Deine eigenen Legenden sind auch hier.",
  "⭐ Efsanelerinde · Hayalî Maç Stüdyosu'nda dövüşebilir": "⭐ In Meine Legenden · kann im Traumkampf-Studio kämpfen",
  "Efsanelerim dolu. 👑 Şampiyon Paketi ile 10 efsane.": "Meine Legenden ist voll. 👑 10 Legenden mit dem Champion-Paket.",
  "⭐ Efsanelerime ekle (Hayalî Maç Stüdyosu)": "⭐ Zu Meine Legenden hinzufügen (Traumkampf-Studio)",
  "⭐ EFSANELERİM": "⭐ MEINE LEGENDEN",
  "{0} zirvedeki haliyle kaydedilsin; Hayalî Maç Stüdyosu'nda Conor'a, Khabir'e ve diğer efsanelere karşı dövüşsün.": "Speichere {0} auf dem Höhepunkt und schick sie im Traumkampf-Studio gegen Conor, Khabir und die anderen Legenden.",
  "✓ Efsanelerinde": "✓ In Meine Legenden",
  "Efsanelerim dolu ({0}/{1}). Şampiyon Paketi ile 10 efsane kaydedebilirsin ya da eskisinin yerine kaydedebilirsin.": "Meine Legenden ist voll ({0}/{1}). Speichere mit dem Champion-Paket bis zu 10 Legenden, oder überschreibe die alte.",
