  "Puan: maç +{0}, galibiyet +{1}, bitiriş +{2}, Günün Dövüşü +{3}, Hayalî Maç +{4}, efsane bölümü +{5}": "Punkte: Kampf +{0}, Sieg +{1}, vorzeitiger Sieg +{2}, Kampf des Tages +{3}, Traumkampf +{4}, Legenden-Kapitel +{5}",
