  "Şampiyon Paketi ile her sezon 6 ödül daha: efsanevi sezon şortu, kemer, giriş efekti… Ulaştığın basamakların ödülleri hemen açılır.": "Mit dem Champion-Paket jede Saison 6 Belohnungen mehr: legendäre Saison-Shorts, ein Gürtel, ein Einlaufeffekt… Belohnungen für bereits erreichte Stufen werden sofort freigeschaltet.",
  "Her ay yeni sezon, yeni tema. Sezon bitince alınmayan ödüller kaybolur; aldıkların dolabında kalır.": "Jeden Monat eine neue Saison und ein neues Thema. Nicht abgeholte Belohnungen verschwinden am Saisonende; abgeholte bleiben in deiner Umkleide.",
