  "Rövanşı Kazansaydı": "Wenn er den Rückkampf gewonnen hätte",
  "O gece bir türlü aklından çıkmadı. Boyun kilidi, susan salon, kafesin üstünden atlayanlar.": "Dieser Abend ging dir nie aus dem Kopf. Der Neck Crank, die stille Arena, die Männer, die über den Käfig sprangen.",
  "Ama ya her şey başka türlü olsaydı? Ya rövanş gerçekten yapılsaydı?": "Aber was, wenn alles anders gekommen wäre? Was, wenn der Rückkampf wirklich stattgefunden hätte?",
  "Khabir Nurmagaliev hâlâ kemerin sahibi. Bu kez onu ayakta tutacak, mesafeyi sen belirleyeceksin.": "Khabir Nurmagaliev hält immer noch den Gürtel. Diesmal hältst du ihn im Stand und kontrollierst die Distanz.",
  "Khabir Nurmagaliev'i yen": "Schlag Khabir Nurmagaliev",
  "Hafif sıklete dön: Nurmagaliev kemerin sahibi olarak orada bekliyor.": "Geh zurück ins Leichtgewicht: Nurmagaliev wartet dort als Champion.",
  "Hafif sıklet kemerini al": "Gewinne den Leichtgewichtsgürtel",
  "Rövanş PPV payı": "PPV-Anteil des Rückkampfs",
  "🔀 Tarih yeniden yazıldı: rövanşı kazanan sensin.": "🔀 Geschichte neu geschrieben: Du hast den Rückkampf gewonnen.",
  "Hiç Sorun Çıkarmasaydı": "Wenn er sich aus Ärger rausgehalten hätte",
  "Cezalar, kayıp yıllar, manşetlere düşen gece yarısı haberleri… Hiçbiri yaşanmasaydı?": "Sperren, verlorene Jahre, Schlagzeilen um Mitternacht… Was, wenn nichts davon passiert wäre?",
  "Bu kez erken yatıyorsun, salona ilk sen giriyorsun, telefonunu kapatıyorsun.": "Diesmal gehst du früh ins Bett, bist als Erster im Gym, schaltest dein Handy aus.",
  "Soru basit: en iyi hâlin, kesintisiz bir seri yapsa nereye kadar gider?": "Die Frage ist einfach: Wie weit kommt dein bestes Ich ohne Unterbrechung?",
