  "Herkes zirvede bıraktığını söyledi. Ama ya bırakmasaydın?": "Alle sagten, du bist auf dem Höhepunkt gegangen. Aber was, wenn du nicht gegangen wärst?",
  "Welter sıklette yeni bir kral var: Kamaru Usmanov. Güçlü, sabırlı, durdurulamaz.": "Im Weltergewicht gibt es einen neuen König: Kamaru Usmanov. Stark, geduldig, unaufhaltsam.",
