  "Tek seferlik alım: sınırsız antrenör kariyeri, bütün beceriler, Yılın Antrenörü ödülleri ve UCC şampiyonları.": "Einmaliger Kauf: eine unbegrenzte Trainerkarriere, alle Fähigkeiten, Auszeichnungen als Trainer des Jahres und UCC-Champions.",
