  "Bu gece senin kariyerini bitireceğim.": "Heute Nacht beende ich deine Karriere.",
  "Herkes beni konuşacak, sen de dahil.": "Alle werden über mich reden, du auch.",
  "O kemer zaten benim, sadece takacağım.": "Der Gürtel gehört schon mir, ich lege ihn nur noch an.",
  "Sen sadece bir basamaksın.": "Du bist nur ein Sprungbrett.",
