  "Bu sefer kafese sen çıkmıyorsun. Dövüşçülerin kariyeri, parası ve sağlığı senin telefonunda.": "Diesmal steigst nicht du in den Käfig. Karriere, Geld und Gesundheit deiner Kämpfer liegen auf deinem Handy.",
