  "Yetenek avına çık, gençleri komisyon pazarlığıyla imzala, rakip ajanslardan önce davran.": "Geh auf Talentsuche, verpflichte Junge mit Provisionsverhandlungen und sei schneller als die Konkurrenz.",
  "İki dövüşçün aynı kemere yürürse? Organizasyon onları birbirine eşlemek isteyecek.": "Was, wenn zwei deiner Kämpfer um denselben Gürtel kämpfen? Die Organisation will sie gegeneinander antreten lassen.",
  "Doktor uyarır, para çağırır. Dövüşçünün sağlığı mı, maaş günü mü?": "Der Arzt warnt, das Geld lockt. Gesundheit deines Kämpfers oder Zahltag?",
