  "Bütün modların aynı dünyada geçiyor. Kariyerindeki dövüşçülerin Menajer Modu'nda rakip olarak teklif edilir; Menajer Modu'ndaki dövüşçülerin de büyük ligde ve UCC'de kariyerinin karşısına çıkar.": "Alle deine Modi spielen in derselben Welt. Deine Karrierekämpfer werden im Manager-Modus als Gegner angeboten, und deine Manager-Kämpfer treten in den großen Ligen und in der UCC gegen deine Karriere an.",
  "ÇAPRAZ MAÇ": "CROSSOVER",
  "ÇAPRAZ MAÇLAR": "CROSSOVER-KÄMPFE",
  "Henüz modlar arası maç yok. Büyük lige çıktıkça ve Menajer Modu'nda teklifler geldikçe dövüşçülerin karşılaşacak.": "Noch keine Crossover-Kämpfe. Sobald du in die großen Ligen kommst und im Manager-Modus Angebote eintreffen, treffen deine Kämpfer aufeinander.",
  "Bağlantı için iki tarafta da dövüşçü gerekir: aktif bir kariyer ve Menajer Modu'nda aynı sıklette bir dövüşçü.": "Du brauchst Kämpfer auf beiden Seiten: eine aktive Karriere und einen Kämpfer derselben Gewichtsklasse im Manager-Modus.",
