  "Kampın nasıl geçti? Bu maç için ne değiştirdin?": "Wie lief das Camp? Was hast du für diesen Kampf geändert?",
  "“Her gün biraz daha iyi olmaya çalıştık. Gerisini kafeste göreceğiz.”": "„Wir wollten jeden Tag ein bisschen besser werden. Den Rest sehen wir im Käfig.“",
  "“Ekibime güveniyorum. İşimizi yaptık.”": "„Ich vertraue meinem Team. Wir haben unseren Job gemacht.“",
  "“Bu kampta onu üç kez yendim, sparringde. Cumartesi dördüncüsü.”": "„Ich habe ihn in diesem Camp dreimal geschlagen, im Sparring. Samstag ist das vierte Mal.“",
  "“Hiç bu kadar hazır olmadım. Şanssızlığı onun.”": "„Ich war noch nie so bereit. Pech für ihn.“",
  "“Değişen tek şey diyetim. Özledim pideyi.”": "„Geändert hat sich nur meine Diät. Ich vermisse Pizza.“",
  "“Hocam bağırmaktan sesini kaybetti, demek ki iyi geçti.”": "„Mein Trainer hat vom Brüllen seine Stimme verloren, also lief es gut.“",
  "“Her şey sizin için. İyi ki varsınız.”": "„Alles für euch. Schön, dass es euch gibt.“",
  "“Desteğinizi hissediyorum. Sizi mahcup etmeyeceğim.”": "„Ich spüre eure Unterstützung. Ich lasse euch nicht hängen.“",
  "“Tribünleri doldurun, bir şov izleyeceksiniz.”": "„Füllt die Ränge, ihr werdet eine Show sehen.“",
  "“Bayramı şimdiden hazırlayın.”": "„Bereitet schon mal die Party vor.“",
  "“Bilet alanlar arkada oturmasın, önde daha çok kan var.”": "„Wer ein Ticket hat, nicht hinten sitzen, vorne gibt’s mehr Blut.“",
  "“Cumartesiden sonra hepinize çay benden.”": "„Nach Samstag geht der Tee auf mich.“",
  "{0} senin en zayıf yanını bulduğunu söylüyor. Ne diyeceksin?": "{0} sagt, er hat deine größte Schwäche gefunden. Was sagst du?",
  "“Herkesin zayıf yanı vardır. Ben de kendiminkini çalıştım.”": "„Jeder hat Schwächen. Ich habe an meinen gearbeitet.“",
  "“Bulmuşsa iyi, ben de onunkini buldum.”": "„Gut, wenn er sie gefunden hat, ich habe seine auch.“",
  "“Zayıf yanım mı? Onu bulmak için önce ayakta kalması lazım.”": "„Meine Schwäche? Dafür müsste er erst mal stehen bleiben.“",
  "“Bulsun. Cumartesi aramaya vakti olmayacak.”": "„Soll er doch. Am Samstag hat er keine Zeit zum Suchen.“",
  "“Zayıf yanım tatlı. Kafeste tatlı yok, sorun yok.”": "„Meine Schwäche sind Süßigkeiten. Im Käfig gibt es keine, also kein Problem.“",
  "“Bunu söylemesi bile bir zayıflık aslında.”": "„So etwas zu sagen, ist schon eine Schwäche.“",
  "Ne zaman emekli olmayı düşünüyorsun?": "Wann denkst du ans Aufhören?",
  "“Vücudum söyleyecek. Şimdilik dinliyor.”": "„Mein Körper wird es mir sagen. Noch hört er auf mich.“",
  "“Daha yolun başındayım gibi hissediyorum.”": "„Ich fühle mich, als würde ich gerade erst anfangen.“",
  "“Bütün rekorları kırınca. Yani biraz daha var.”": "„Wenn ich alle Rekorde gebrochen habe. Also dauert es noch.“",
  "“Rakip kalmadığında. Takvimi ona göre ayarlayın.”": "„Wenn keine Gegner mehr übrig sind. Plant den Kalender danach.“",
  "“Emeklilik maaşı yeterse yarın. Yetmiyor, devam.”": "„Morgen, wenn die Rente reicht. Reicht sie nicht, also weiter.“",
  "“Torunum beni yenince.”": "„Wenn mein Enkel mich schlägt.“",
  "Bu maçtan ne kadar kazanacaksın?": "Wie viel verdienst du an diesem Kampf?",
  "“Para önemli ama kemer daha önemli.”": "„Geld ist wichtig, aber der Gürtel wichtiger.“",
  "“Hak ettiğim kadar. Gerisi menajerin işi.”": "„So viel, wie ich verdiene. Der Rest ist Sache meines Managers.“",
  "“Yetmez. Bir sonrakinde iki katını isteyeceğim.”": "„Nicht genug. Beim nächsten Mal will ich das Doppelte.“",
  "“Onun bütün kariyerinde kazandığından fazla.”": "„Mehr, als er in seiner ganzen Karriere verdient hat.“",
  "“Yeni bir araba alacak kadar. Park yeri bulamayacak kadar değil.”": "„Genug für ein neues Auto. Nicht genug, um einen Parkplatz zu finden.“",
  "“Annem duyunca hemen fatura listesi yolladı.”": "„Meine Mutter hat’s gehört und sofort die Rechnungen geschickt.“",
  "Sosyal medyada {0} ile atışmanız gündem oldu. Bu iş kafeste mi bitecek?": "Dein Schlagabtausch mit {0} in den sozialen Medien ging viral. Endet das im Käfig?",
  "“Sosyal medya bir şey, kafes başka. Ben kafese bakarım.”": "„Social Media ist das eine, der Käfig das andere. Ich konzentriere mich auf den Käfig.“",
  "“Klavye arkasında herkes cesur. Cumartesi göreceğiz.”": "„Hinter der Tastatur ist jeder mutig. Am Samstag sehen wir weiter.“",
