  "{0}: “Bu cümleyi çerçeveletip duvarına as, son kez söylüyorsun.”": "{0}: „Rahm dir den Satz ein und häng ihn an die Wand, du sagst ihn zum letzten Mal.“",
  "{0}: “Gülmek serbest, cumartesi ağlamak da.”": "{0}: „Lachen ist erlaubt, am Samstag auch Weinen.“",
