  "{0} sinirle omuz silkti, köşesine yürüdü.": "{0} zuckte wütend mit den Schultern und ging in seine Ecke.",
  "{0}: “Bu gece kazandın, cumartesi benim.”": "{0}: „Heute hast du gewonnen, Samstag gehört mir.“",
  "{0} kameralara döndü: “Gördünüz mü, şimdiden korkuyor.”": "{0} drehte sich zu den Kameras: „Seht ihr? Er hat jetzt schon Angst.“",
  "{0} giderken arkasından seslendi: “Cumartesi daha kötü olacak!”": "{0} rief im Gehen: „Am Samstag wird es schlimmer!“",
